comms.text:
@1 וַהֲוָה מִסּוֹף תַּרְתֵּין שְׁנִין וּפַרְעֹה חָלֵם וְהָא קָאֵם עַל נַהֲרָא:
@2 וְהָא מִן נַהֲרָא סָלְקָן שְׁבַע תּוֹרָן שַׁפִּירָן לְמֶחֱזֵי וּפַטִּימָן בְּשָׂר וְרָעְיָן בְּאַחְוָה:
@3 וְהָא שְׁבַע תּוֹרָן אָחֳרָנְיָן סָלְקָן בַּתְרֵיהוֹן מִן נַהֲרָא בִּישָׁן לְמֶחֱזֵי וַחֲסִירַן בְּשָׂר וְקָמָן לְקִבְלֵיהוֹן דְּתוֹרָן עַל כֵּיף נַהֲרָא:
@4 וַאֲכָלַן תּוֹרְתָּא בִּישָׁן לְמֶחֱזֵי וַחֲסִירַן בְּשַׂר יָת שְׁבַע תּוֹרְתָּא שַׁפִּירָן לְמֶחֱזֵי וּפַטִּימָתָא וְאִתְּעַר פַּרְעֹה:
@5 וּדְמוּךְ וַחֲלַם תִּנְיָנוּת וְהָא שְׁבַע שֻׁבְּלַיָּא סָלְקָן בְּקַנְיָא חַד פַּטִּימָן וְטָבָן:
@6 וְהָא שְׁבַע שֻׁבְּלַיָּא לָקְיָן וּשְׁקִיפָן קִדּוּם צָמְחָן בַּ:תרֵיהוֹן:
@7 וּבְלָעָא שֻׁבְּלַיָּא לָקְיָתָא יָת שְׁבַע שֻׁבְּלַיָּא פַּטִּימָתָא וּמָלְיָתָא וְאִתְּעַר פַּרְעֹה וְהָא חֶלְמָא:
@8 וַהֲוָה בְצַפְרָא וּמִטַּרְפָּא רוּחֵהּ וּשְׁלַח וּקְרָא יָת כָּל חֳרָשֵׁי מִצְרַיִם וְיָת כָּל חַכִּימָהָא וְאִשְׁתָּעִי פַרְעֹה לְהוֹן יָת חֶלְמֵהּ וְלֵית דְּפָשַׁר יָתְהוֹן לְפַרְעֹה:
@9 וּמַלִּיל רַב שָׁקֵי (עִם פַּרְעֹה) לְפַרְעֹה לְמֵימָר יָת סָרְחָנִי אֲנָא מַדְכַּר יוֹמָא דֵּין:
@10 פַּרְעֹה רְגֵז עַל עַבְדוֹהִי וִיהַב יָתִי בְּמַטְּרָא בֵּית רַב קָטוֹלַיָּא יָתִי וְיָת רַב נַחְתּוֹמֵי:
@11 וַחֲלֵמְנָא חֶלְמָא בְּלֵילְיָא חַד אֲנָא וָהוּא גְּבַר כְּפִשְׁרַן חֶלְמֵהּ חֲלֵמְנָא:
@12 וְתַמָּן עִמָּנָא עוּלֵם עִבְרָאָה עַבְדָא לְרַב קָטוֹלַיָּא וְאִשְׁתָּעֵינָא לֵהּ וּפָשַׁר לָנָא יָת חֶלְמָנָא גְּבַר כְּחֶלְמֵהּ פָּשָׁר:
@13 וַהֲוָה כְּמָא דִּי פָשַׁר לָנָא כֵּן הֲוָה יָתִי אֲתֵיב עַל שִׁמּוּשִׁי וְיָתֵהּ צְלָב:
@14 וּשְׁלַח פַּרְעֹה וּקְרָא יָת יוֹסֵף וְאַרְהָטוּהִי מִן בֵּית אֲסִירֵי וְסַפַּר וְשַׁנִּי כְסוּתֵהּ וְעַל לְוַת פַּרְעֹה:
@15 וַאֲמַר פַּרְעֹה לְיוֹסֵף חֶלְמָא חֲלֵמִית וּפָשַׁר לֵית לֵהּ וַאֲנָא שִׁמְעֵית עֲלָךְ לְמֵימַר דְּאַתְּ שָׁמַע חֶלְמָא לְמִפְשַׁר יָתֵהּ:
@16 וַאֲתֵיב יוֹסֵף יָת פַּרְעֹה לְמֵימַר בַּר מִן חָכְמְתִי אֶלָּהֵן מִן קֳדָם יְיָ יִתֹּתַב יָת שְׁלָמָא דְפַרְעֹה:
@17 וּמַלֵּיל פַּרְעֹה עִם יוֹסֵף בְּחֶלְמִי הָא אֲנָא קָאֵם עַל כֵּיף נַהֲרָא:
@18 וְהָא מִן נַהֲרָא סָלְקָן שְׁבַע תּוֹרָן פַּטִּימָן בְּשַׂר וְשַׁפִּירָן לְמֶחֱזֵי וְרַעְיָן בְּאַחֲוָה:
@19 וְהָא שְׁבַע תּוֹרָן אָחֳרָנְיָן סָלְקָן בַּתְרֵיהוֹן חֲסִיכָן וּבִישָׁן לְמֶחֱזֵי לַחֲדָא וַחֲסִירָן בְּשָׂר לָא חֲזֵתִי כְוָתְהֵן בְּכָל אַרְעָא דְמִצְרַיִם לְבִישׁוּ:
@20 וַאֲכָלָן תּוֹרְתָּא חֲסִיכָתָא וּבִישָׁתָא יָת שְׁבַע תּוֹרְתָּא קַדְמָיָתָּא פַּטִּימָתָא:
@21 וַעֲלָא לִמְעֵיהֶן וְלָא אִתְיְדַע אֲרֵי עַלּוּ לִמְעֵיהֶן וּמֶחֱזֵיהֶן בִּישׁ כַּד בְּקַדְמֵיתָא וְאִתְּעָרִית:
@22 וַחֲזֵית בְּחֶלְמִי וְהָא שְׁבַע שֻׁבְּלַיָּא סָלְקָן בְּקַנְיָא חַד מָלְיָן וְטָבָן:
@23 וְהָא שְׁבַע שֻׁבְּלַיָּא נָצָן לָקְיָן שְׁקִיפָן קִדּוּם צָמְחָן בַּתְרֵיהוֹן:
@24 וּבְלָעָן שֻׁבְּלַיָּא לָקְיָתָא יָת שְׁבַע שֻׁבְּלַיָּא טָּבָתָא וַאֲמָרִית לַחֲרָשַׁיָּא וְלֵית דִּי מְחַוֵּי לִי:
@25 וַאֲמַר יוֹסֵף לְפַרְעֹה חֶלְמָא דְפַּרְעֹה חַד הוּא יָת דִּי יְיָ עָתִיד לְמֶעְבַּד חַוִּי לְפַרְעֹה:
@26 שְׁבַע תּוֹרְתָּא טָבָתָא שְׁבַע שְׁנִין אִנּוּן וּשְׁבַע שֻׁבְּלַיָּא טָבָתָא שְׁבַע שְׁנִין אִנּוּן חֶלְמָא חַד הוּא:
@27 וּשְׁבַע תּוֹרְתָּא חֲסִיכָתָא וּבִישָׁתָא דְסָלְקָן בַּתְרֵיהוֹן שְׁבַע שְׁנִין אִנּוּן וּשְׁבַע שֻׁבְּלַיָּא לָקְיָתָא דִּשְׁקִיפָן קִדּוּם יְהֶוְיָן שְׁבַע שְׁנֵי כַפְנָא:
@28 הוּא פִתְגָּמָא דִּי מַלֵּילִית עִם פַּרְעֹה דִּי יְיָ עָתִיד לְמֶעְבַּד אַחֲזֵי לְפַרְעֹה:
@29 הָא שְׁבַע שְׁנִין אָתְיָן שׂוֹבְעָא רַבָּא בְּכָל אַרְעָא דְמִצְרָיִם:
@30 וִיקוּמוּן שְׁבַע שְׁנֵי כַפְנָא בַּתְרֵיהֶן וְיִתִנְשֵׁי כָּל שׂוֹבְעָא בְּאַרְעָא דְמִצְרָיִם וִישֵׁיצֵי כַפְנָא יָת (עַמָּא דְ) אַרְעָא:
@31 וְלָא יִתְיְדַע שׂוֹבְעָא בְּאַרְעָא מִן קֳדָם כַּפְנָא הַהוּא דִּיהֵי בָתַר כֵּן אֲרֵי תַקִּיף הוּא לַחֲדָא:
@32 וְעַל דְּאִתַּנֵּית חֶלְמָא לְפַרְעֹה תַּרְתֵּין זִמְנִין אֲרֵי תַקִּין פִּתְגָּמָא מִן קֳדָם יְיָ וְאוֹחִי יְיָ לְמֶעְבְּדֵהּ:
@33 וּכְעַן יֶחֱזֵי פַרְעֹה גְּבַר סוּכְלְתָן וְחַכִּים וִימַנִינֵיהּ עַל אַרְעָא דְמִצְרָיִם:
@34 יַעְבֵּד פַרְעֹה וִימַנֵּי מְהֵימְנִין עַל אַרְעָא וִיזָרֵז יָת אַרְעָא דְמִצְרַיִם בְּשֶׁבַע שְׁנֵי שׂוֹבְעָא:
@35 וְיִכְנְשׁוּן יָת כָּל עִיבוּר שְׁנַיָּא טָבָן דְּאָתְיָן הָאִלֵּין וְיִצְבְּרוּן עִיבוּרָא תְּחוֹת יְדָא מְהֵימְנֵי דְפַרְעֹה עִיבוּרָא בְּקִירְוַיָּא וְיִטְּרוּן:
@36 וִיהֵי עִיבוּרָא גְּנִיז (לְעַמָּא דְ) לְאַרְעָא לִשְׁבַע שְׁנֵי כַפְנָא דִּי תְהֶוְיָן בְּאַרְעָא דְמִצְרָיִם וְלָא תִשְׁתֵּיצֵי עַמָּא דְאַרְעָא בְּכַפְנָא:
@37 וּשְׁפַר פִּתְגָּמָא בְּעֵינֵי פַרְעֹה וּבְעֵינֵי כָּל עַבְדּוֹהִי:
@38 וַאֲמַר פַּרְעֹה לְעַבְדוֹהִי הֲנִשְׁכַּח כְּדֵין גְּבַר דִּי רוּחַ נְבוּאָה מִן קֳדָם יְיָ בֵּהּ:
@39 וַאֲמַר פַּרְעֹה לְיוֹסֵף בָּתַר דְּאוֹדַע יְיָ יָתָךְ יָת כָּל דָּא לֵית סָכְלְתָן וְחַכִּים כְּוָתָךְ:
@40 אַתְּ תְּהֵי מְמַנָּא עַל בֵּיתִי וְעַל מֵימְרָךְ יִתְּזַן כָּל עַמִּי לְחוֹד כָּרְסֵי מַלְכוּתָא הָדֵין אֵיהֵי יַקִּיר מִנָּךְ:
@41 וַאֲמַר פַּרְעֹה לְיוֹסֵף חֲזֵי מַנֵּיתִי יָתָךְ עַל כָּל אַרְעָא:דמִצְרָיִם:
@42 וְאַעְדִּי פַרְעֹה יָת עִזְקְתֵהּ מֵעַל יְדֵהּ וִיהַב יָתַהּ עַל יְדָא דְיוֹסֵף וְאַלְבִּישׁ יָתֵהּ לְבוּשִׁין דְּבוּץ וְשַׁוִּי מָנִיכָא דְדַהֲבָא עַל צַוְּארֵהּ:
@43 וְאַרְכֵּיב יָתֵהּ בִּרְתִכָּא תִנְיֵתָא (נ''י תִנְיָנָא) דִּי לֵהּ וְאַכְרִיזוּ קֳדָמוֹהִי דֵּין אַבָּא לְמַלְכָּא וּמַנִּי יָתֵהּ עַל כָּל אַרְעָא דְמִצְרָיִם:
@44 וַאֲמַר פַּרְעֹה לְיוֹסֵף אֲנָא פַרְעֹה וּבַר מֵימְרָךְ לָא יְרִים גְּבַר יָת יְדֵהּ לְמֵיחַד זֵין וְיָת רִגְלֵהּ לְמִרְכַּב עַל סוּסְיָא בְּכָל אַרְעָא דְמִצְרָיִם:
@45 וּקְרָא פַּרְעֹה שׁוּם יוֹסֵף גַּבְרָא דְמִטַּמְרָן גָּלְיָן לֵהּ וִיהַב לֵהּ יָת אָסְנַת בַּת פּוֹטִי פֶרַע רַבָּא דְאוֹן לְאִתְּתָא וּנְפַק יוֹסֵף (שַׁלִּיט) עַל אַרְעָא דְמִצְרָיִם:
@46 וְיוֹסֵף בַּר תְּלָתִין שְׁנִין כַּד קָם קֳדָם פַּרְעֹה מַלְכָּא דְמִצְרָיִם וּנְפַק יוֹסֵף מִן קֳדָם פַּרְעֹה וַעֲבַר (שַׁלִּיט) בְּכָל אַרְעָא דְמִצְרָיִם:
@47 וּכְנָשׁוּ דָיְרֵי אַרְעָא בִּשְׁבַע שְׁנֵי שׂוֹבְעָא עִיבוּרָא לְאוֹצָרִין:
@48 וּכְנַשׁ יָת כָּל עִיבוּר שְׁבַע שְׁנִין דִּי הֲווֹ בְּאַרְעָא דְמִצְרַיִם וִיהַב עִיבוּר בְּקִרְוַיָּא עִיבוּר חֲקַל קַרְתָּא דִּי בְסַחְרָנָהָא יְהַב בְּגַוָּהּ:
@49 וּכְנַשׁ יוֹסֵף עִיבוּרָא כְּחַלָּא דְיַמָּא סַגִּי לַחֲדָא עַד דִּי פְסַק לְמִמְנֵי אֲרֵי לֵית מִנְיָן:
@50 וּלְיוֹסֵף אִתְיְלִיד תַּרְתֵּין בְּנִין עַד לָא עַלַּת שַׁתָּא דְכַפְנָא דִּילִידַת לֵהּ אָסְנַת בַּת פּוֹטִי פֶרַע רַבָּא דְאוֹן:
@51 וּקְרָא יוֹסֵף יָת שׁוּם בּוּכְרָא מְנַשֶּׁה אֲרֵי אַנְשְׁיַנִי יְיָ יָת כָּל עַמְלִי וְיָת כָּל בֵּית אַבָּא:
@52 וְיָת שׁוּם תִּנְיָנָא קְרָא אֶפְרָיִם אֲרֵי אַפְשַׁנִּי יְיָ בְּאַרַע שִׁעְבּוּדִי:
@53 וּשְׁלִימַת שְׁבַע שְׁנֵי שׂוֹבְעָא דִּי הֲוָה בְּאַרְעָא דְמִצְרָיִם:
@54 וּשְׁרִיאַת שְׁבַע שְׁנֵי כַפְנָא לְמֵיעַל כְּמָא דִּי אֲמַר יוֹסֵף וַהֲוָה כַפְנָא בְּכָל אַרְעֲתָא וּבְכָל אַרְעָא דְמִצְרַיִם הֲוָה לַחְמָא:
@55 וּכְפָנַת כָּל אַרְעָא דְמִצְרַיִם וּצְוַח עַמָּא קֳדָם לְפַרְעֹה עַל לַחְמָא וַאֲמַר פַּרְעֹה לְכָל מִצְרָאֵי אִיזִילוּ לְוַת יוֹסֵף דִּי יֵימַר לְכוֹן תַּעְבְּדוּן:
@56 וְכַפְנָא הֲוָה עַל כָּל אַפֵּי אַרְעָא וּפְתַח יוֹסֵף יָת כָּל דִּי בְהוֹן עִיבוּרָא וְזַבִּין לְמִצְרַיִם וּתְקֵיף כַּפְנָא בְּאַרְעָא דְמִצְרָיִם:
@57 וְכָל דָּיְרֵי אַרְעָא עַלּוּ לְמִצְרַיִם לְמִזְבַּן עִיבוּרָא מִן יוֹסֵף אֲרֵי תְקֵיף כַּפְנָא בְּכָל אַרְעָא:
@58 וַחֲזָא יַעֲקֹב אֲרֵי אִית עִיבוּרָא מִזְדַּבַּן בְּמִצְרָיִם וַאֲמַר יַעֲקֹב לִבְנוֹהִי לְמָא תִּתְחֲזוּן:
@59 וַאֲמַר הָא שְׁמָעִית אָמְרִין אֲרֵי אִית עִיבוּרָא מִזְדַּבַּן בְּמִצְרָיִם חוּתוּ תַמָּן וּזְבוּנוּ לָנָא מִּתַּמָּן וְנֵחֵי וְלָא נְמוּת:
@60 וּנְחָתוּ אֲחֵי יוֹסֵף עַסְרָא לְמִזְבַּן עִיבוּרָא מִמִּצְרָיִם:
@61 וְיָת בִּנְיָמִין אֲחוּהִי דְיוֹסֵף לָא שְׁלַח יַעֲקֹב עִם אֲחוֹהִי אֲרֵי אֲמַר דִּלְמָא יְעַרְעִנֵּהּ מוֹתָא:
@62 וַאֲתוֹ בְּנֵי יִשְׂרָאֵל לְמִזְבַּן עִיבוּרָא בְּגוֹ עָלַיָּא אֲרֵי הֲוָה כַפְנָא בְּאַרְעָא דִּכְנָעַן:
@63 וְיוֹסֵף הוּא דְּשַׁלִּיט עַל אַרְעָא הוּא דְזַבִּין עִיבוּרָא לְכָל עַמָּא דְאַרְעָא וַאֲתוֹ אֲחֵי יוֹסֵף וּסְגִידוּ לֵהּ עַל אַפֵּיהוֹן עַל אַרְעָא:
@64 וַחֲזָא יוֹסֵף יָת אֲחוֹהִי וְאִשְׁתְּמוֹדְעִנּוּן וְחַשִּׁיב מָה דְמַלֵּיל לְהוֹן וּמַלִּיל עִמְּהוֹן קַשְׁיָן וַאֲמַר לְהוֹן מְנָן אֲתֵיתוּן וַאֲמָרוּ מֵאַרְעָא דִּכְנַעַן לְמִזְבַּן עִיבוּרָא:
@65 וְאִשְׁתְּמוֹדַע יוֹסֵף יָת אֲחוֹהִי וְאִנּוּן לָא אִשְׁתְּמוֹדְעוֹהִי:
@66 וּדְכִיר יוֹסֵף יָת חֶלְמַיָּא דִּי חֲלִים לְהוֹן וַאֲמַר לְהוֹן מְאַלְלִין אַתּוּן לְמֶחֱזֵי יָת בִּדְקָא דְאַרְעָא אֲתֵיתוּן:
@67 וַאֲמָרוּ לֵהּ לָא רִבּוֹנִי וְעַבְדָּיךְ עַלּוּ לְמִזְבַּן עִיבוּרָא:
@68 כֻּלָּנָא בְּנֵי גַּבְרָא חַד נָחְנָא כֵּיוָנֵי אֲנַחְנָא לָא הֲווֹ עַבְדָיךְ אַלִּילֵי:
@69 וַאֲמַר לְהוֹן לָא אֲרֵי בִדְקָא דְאַרְעָא אֲתֵיתוּן לְמֶחֱזֵי:
@70 וַאֲמָרוּ תְּרֵין עֲשַׂר עַבְדָיךְ אַחִין אֲנַחְנָא בְּנֵי גַּבְרָא חַד בְּאַרְעָא דִּכְנָעַן וְהָא זְעֵירָא עִם אָבוּנָא יוֹמָא דֵּין וְחַד לֵיתוֹהִי:
@71 וַאֲמַר לְהוֹן יוֹסֵף הוּא דִּי מַלֵּילִית עִמְּכוֹן לְמֵימַר אַלִּילֵי אַתּוּן:
@72 בְּדָא תִּתְבַּחֲרוּן חֵי פַרְעֹה אִם תִּפְקוּן מִכָּא אֶלָּהֵין בְּמֵתֵי אֲחוּכוֹן זְעֵירָא הָכָא:
@73 שְׁלָחוּ מִנְּכוֹן חַד וְיִדְבַּר יָת אֲחוּכוֹן וְאַתּוּן תִּתְאַסְרוּן וְיִתְבַּחֲרוּן פִּתְגָּמֵיכוֹן הַקְּשׁוֹטּ אַתּוּן אָמְרִין וְאִם לָא חֵי פַרְעֹה אֲרֵי אַלִּילֵי אַתּוּן:
@74 וּכְנַשׁ יָתְהוֹן לְבֵית מַטְרָא תְּלָתָא יוֹמִין:
@75 וַאֲמַר לְהוֹן יוֹסֵף בְּיוֹמָא תְלִיתָאָה דָּא עִבִידוּ וְאִתְקַיָּמוּ מִן קֳדָם יְיָ אֲנָא דָּחֵל:
@76 אִם כֵּיוָנֵי אַתּוּן אֲחוּכוֹן חַד יִתְאַסַּר בְּבֵית מַטַּרְתְּכוֹן וְאַתּוּן אִיזִילוּ אוֹבִילוּ עִיבוּרָא דְּחַסִּיר בְּבָתֵּיכוֹן:
@77 וְיָת אֲחוּכוֹן זְעֵירָא תַּיְתוּן לְוָתִי וְיִתְהֵמְנוּן פִּתְגָּמֵיכוֹן וְלָא תְמוּתוּן וַעֲבָדוּ כֵן:
@78 וַאֲמָרוּ גְּבַר לַאֲחוּהִי בְּקוּשְׁטָּא חַיָּבִין אֲנַחְנָא עַל אָחוּנָא דִּי חֲזֵינָא עָקַת נַפְשֵׁהּ כַּד הֲוָה מִתְחַנֶּן לָנָא וְלָא קַבֵּלְנָא מִנֵּהּ עַל כֵּן אָתַת לְוָתָנָא עַקְתָא הָדָא:
@79 וַאֲתֵיב רְאוּבֵן יָתְהוֹן לְמֵימָר הֲלָא אֲמָרִית לְוָתְכוֹן לְמֵימַר לָא תְחוֹבוּן בְּעוּלֵימָא וְלָא קַבֶּלְתּוּן וְאַף דְּמֵהּ הָא מִתְבְּעֵי:
@80 וְאִנּוּן לָא יָדְעוּן אֲרֵי שְׁמִיעַ יוֹסֵף אֲרֵי מְתֻרְגְּמָן הֲוָה בֵינֵיהוֹן:
@81 וְאִסְתַּחַר מֵעִלָּוֵיהוֹן וּבְכָא וְתָב לְוָתְהוֹן וּמַלֵּיל עִמְּהוֹן וּדְבַר מִלְּוַתְהוֹן יָת שִׁמְעוֹן וַאֲסַר יָתֵהּ לְעֵינֵיהוֹן:
@82 וּפַקֵּיד יוֹסֵף וּמְלוֹ יָת מָנֵיהוֹן עִיבוּרָא וְלַאֲתָבָא כַסְפֵּיהוֹן גְּבַר לְסַקֵּהּ וּלְמִתַּן לְהוֹן זְוָדִין לְאָרְחָא וַעֲבַד לְהוֹן כֵּן:
@83 וּנְטָלוּ יָת עִיבוּרְהוֹן עַל חֲמָרֵיהוֹן וַאֲזָלוּ מִתַּמָּן:
@84 וּפְתַח חַד יָת סַקֵּהּ לְמִתַּן כִּסְתָא לַחֲמָרֵהּ בְּבֵית מְבָתָא וַחֲזָא יָת כַּסְפֵּהּ וְהָא הוּא בְּפוּם טוֹעֲנֵהּ:
@85 וַאֲמַר לַאֲחוֹהִי אִתּוֹתַב כַּסְפִּי וְאַף הָא בְטּוֹעֲנִי וּנְפַק מַדַּע לִבְּהוֹן וּתְוָהוּ גְּבַר לַאֲחוּהִי לְמֵימַר מָה דָּא עֲבַד יְיָ לָנָא:
@86 וַאֲתוֹ לְוַת יַעֲקֹב אֲבוּהוֹן אַרְעָא דִּכְנָעַן וְחַוִּיוּ לֵהּ יָת כָּל דְעַרְעָא יָתְהוֹן לְמֵימָר:
@87 מַלֵּיל גַּבְרָא רִבּוֹנָא דְאַרְעָא עִמָּנָא קַשְׁיָן וִיהַב יָתָנָא כִּמְאַלִּילֵי יָת אַרְעָא:
@88 וַאֲמַרְנָא לֵהּ כֵּיוָנֵי אֲנָחְנָא לָא הֲוֵינָא אַלִּילֵי:
@89 תְּרֵין עֲסַר אֲנַחְנָא אַחִין בְּנֵי אָבוּנָא חַד לֵיתוֹהִי וּזְעֵירָא יוֹמָא דֵּין עִם אָבוּנָא בְּאַרְעָא דִּכְנָעַן:
@90 וַאֲמַר לָנָא גַּבְרָא רִבּוֹנָא דְּאַרְעָא בְּדָא אִדַּע אֲרֵי כֵיוָנֵי אַתּוּן אֲחוּכוֹן חַד שְׁבוּקוּ לְוָתִי וְיָת עִיבוּרָא דְחַסִּיר בְּבָתֵּיכוֹן סִיבוּ וֶאֱזִילוּ:
@91 וְאַיְתִיאוּ יָת אֲחוּכוֹן זְעֵירָא לְוָתִי וְאִדַּע אֲרֵי לָא אַלִּילֵי אַתּוּן אֲרֵי כֵיוָנֵי אַתּוּן יָת אֲחוּכוֹן אֶתֵּן לְכוֹן וְיָת אַרְעָא תַּעְבְּדוּן בַּהּ סְחוֹרְתָּא:
@92 וַהֲוָה אִנּוּן מְרִיקִין סַקֵּיהוֹן וְהָא גְּבַר צְרִיר כַּסְפֵּהּ בְּסַקֵּהּ וַחֲזוֹ יָת צְרָרֵי כַסְפֵּיהוֹן אִנּוּן וַאֲבוּהוֹן וּדְחִילוּ:
@93 וַאֲמַר לְהוֹן יַעֲקֹב אֲבוּהוֹן יָתִי אַתְכֶּלְתּוּן יוֹסֵף לֵיתוֹהִי וְשִׁמְעוֹן לָא הֲוָה הָכָא (לֵיתוֹהִי) וְיָת בִּנְיָמִן תִּדְבְּרוּן עֲלַי הֲווֹ כָלְּהוֹן:
@94 וַאֲמַר רְאוּבֵן לְוַת אֲבוּהִי לְמֵימַר יָת תְּרֵין בְּנַי תְּמִית אִם לָא אַיְתִנֵּהּ לְוָתָךְ הַב יָתֵהּ עַל יְדִי וַאֲנָא אֲתֵבִנֵּהּ לָךְ:
@95 וַאֲמַר לָא יֵחוּת בְּרִי עִמְּכוֹן אֲרֵי אָחוּהִי מִית וְהוּא בִּלְחוֹדוֹהִי אִשְׁתָּאַר וִיעַרְעִנֵּהּ מוֹתָא בְּאָרְחָא דִּי תְהָכוּן בַּהּ וְתַחֲתוּן יָת שִׂיבְתִי בְּדָווֹנָא לִשְׁאוֹל:
@96 וְכַפְנָא תַּקִּיף בְּאַרְעָא:
@97 וַהֲוָה כַּד שֵׁיצִיאוּ לְמֵיכַל יָת עִיבוּרָא דְּאַיְתִיאוּ מִמִּצְרָיִם וַאֲמַר לְהוֹן אֲבוּהוֹן תּוּבוּ זְבוּנוּ לָנָא זעֵיר עִיבוּרָא:
@98 וַאֲמַר לֵהּ:יְהוּדָה לְמֵימָר אַסְהָדָא אַסְהֵד בָּנָא גַּבְרָא לְמֵימָר לָא תֶחֱזוּן אַפַּי אֶלָּהֵין כַּד אָחוּכוֹן עִמְּכוֹן:
@99 אִם אִיתָךְ מְשַׁלַּח יָת אָחוּנָא עִמָּנָא נֵיחוֹת וְנִזְבֵּן לָךְ עִיבוּרָא:
@100 וְאִם לֵיתָךְ מְשַׁלַּח לָא נֵיחוֹת אֲרֵי גַּבְרָא אֲמַר לָנָא לָא תֶחֱזוּן אַפַּי אֶלָּהֵין כַּד אֲחוּכוֹן עִמְּכוֹן:
@101 וַאֲמַר יִשְׂרָאֵל לְמָה אַבְאֶשְׁתּוּן לִי לְחַוָּאָה לְגַבְרָא הַעַד כְּעַן לְכוֹן אָחָא:
@102 וַאֲמָרוּ מִשְׁאַל שָׁאֵל גַּבְרָא לָנָא וּלְיַלָּדוּתָנָא לְמֵימַר הַעַד כְּעַן אֲבוּכוֹן קַיָּם הַאִית לְכוֹן אָחָא וְחַוֵּינָא לֵהּ עַל מֵימַר פִּתְגָּמַיָּא הָאִלֵּין הֲמִדַּע הֲוֵינָא יָדְעִין אֲרֵי יֵימַר אוֹחִיתוּ יָת אֲחוּכוֹן:
@103 וַאֲמַר יְהוּדָה לְיִשְׂרָאֵל אֲבוּהִי שְׁלַח עוּלֵימָא עִמִּי וְנֵקוּם וְנֵזֵיל וְנֵיחֵי וְלָא נְמוּת אַף אֲנַחְנָא אַף אַתְּ אַף טַפְלָנָא:
@104 אֲנָא מְעָרַבְנָא בֵהּ מִן יְדִי תִּבְעִנֵּהּ אִם לָא אַיְתִנֵּהּ לָךְ וַאֲקֵימִנֵּהּ קֳדָמָךְ וְאֵהֵי חָטֵי לָךְ כָּל יוֹמַיָּא:
@105 אֲרֵי אִלּוּלָפוֹן בְּדָא אִתְעַכָּבְנָא אֲרֵי כְעַן תַּבְנָא דְּנַן תַּרְתֵּין זִמְנִין:
@106 וַאֲמַר לְהוֹן יִשְׂרָאֵל אֲבוּהוֹן אִם כֵּן הָכָא דָּא עִיבִידוּ סִיבוּ מִדִּמְשַׁבַּח בְּאַרְעָא בְּמָנֵיכוֹן וְאוֹחִיתוּ לְגַבְרָא תִּקְרֻבְתָּא זְעֵיר קְטַף וּזְעֵיר דְּבַשׁ שְׁעַף וּלְטוֹם בָּטְנִין וְשִׁגְדִּין:
@107 וְכַסְפָּא עַל חַד תְּרֵין סִיבוּ בְיֶדְכוֹן וְיָת כַּסְפָּא דְּאִתּוֹתַב בְּפוּם טוֹעֲנֵיכוֹן תְּתִיבוּן בְּיֶדְכוֹן מָאִים שָׁלוּ הוּא:
@108 וְיָת אֲחוּכוֹן דְּבָרוּ וְקוּמוּ תּוּבוּ לְוַת גַּבְרָא:
@109 וְאֵל שַׁדַּי יִתֵּן לְכוֹן רַחֲמִין קֳדָם גַּבְרָא וְיִפְטַר לְכוֹן יָת אֲחוּכוֹן אָחֳרָנָא וְיָת בִּנְיָמִין וַאֲנָא כְּמָא דְּאִתְכֵּלִית תְּכֵלִית:
@110 וּנְסִיבוּ גֻּבְרַיָּא יָת תִּקְרֻבְתָּא הָדָא וְעַל חַד תְּרֵין כַּסְפָּא נְסִיבוּ בִידֵיהוֹן וּדְבָרוּ יָת בִּנְיָמִן וְקָמוּ וּנְחָתוּ לְמִצְרַיִם וְקָמוּ קֳדָם יוֹסֵף:
@111 וַחֲזָא יוֹסֵף עִמְּהוֹן יָת בִּנְיָמִין וַאֲמַר לְדִי מְמַנָּא עַל בֵּיתֵהּ אָעֵיל יָת גֻּבְרַיָּא לְבֵיתָא וּנְכוֹס נִכְסָתָא וְאַתְקֵין אֲרֵי עִמִּי יֵיכְלוּן גֻּבְרַיָּא בְּשֵׁירוּתָא:
@112 וַעֲבַד גַּבְרָא כְּמָא דִּי אֲמַר יוֹסֵף וְאָעֵיל גַּבְרָא יָת גֻּבְרַיָּא לְבֵית יוֹסֵף:
@113 וּדְחִילוּ גֻּבְרַיָּא אֲרֵי אִתַּעֲלוּ לְבֵית יוֹסֵף וַאֲמָרוּ עַל עֵסַק כַּסְפָּא דְּאִתּוֹתַב בְּטוֹעֲנָנָא בְּקַדְמֵיתָא אֲנַחְנָא מִתַּעֲלִין לְאִתְרַבְרָבָא עֲלָנָא וּלְאִסְתַּקָּפָא עֲלָנָא וּלְמִקְנֵי יָתָנָא לְעַבְדִּין וּלְמִדְבַּר יָת חֲמָרָנָא:
@114 וּקְרִיבוּ לְוַת גַּבְרָא דִּי מְמַנָּא עַל בֵּית יוֹסֵף וּמַלִּילוּ עִמֵּהּ בִּתְרַע בֵּיתָא:
@115 וַאֲמָרוּ בְּבָעוּ רִבּוֹנִי מֵיחַת נִחֵתְנָא בְּקַדְמֵיתָא לְמִזְבַּן עִיבוּרָא:
@116 וַהֲוָה כַּד אָתֵינָא לְבֵית מְבָתָא וּפְתַחְנָא יָת טוֹעֲנָנָא וְהָא כְסַף גְּבַר בְּפוּם טוֹעֲנֵהּ כַּסְפָּנָא בְּמַתְקְלֵהּ וַאֲתֵיבְנָא יָתֵהּ בִּידָנָא:
@117 וְכַסְפָּא אָחֳרָנָא אוֹחִיתְנָא בִידָנָא לְמִזְבַּן עִיבוּרָא לָא יְדַעְנָא מָן שַׁוִּי כַסְפָּנָא בְּטוֹעֲנָנָא:
@118 וַאֲמַר שְׁלַם לְכוֹן לָא תִדְחֲלוּן אֱלָהֲכוֹן וֵאֱלָהָא דַּאֲבוּכוֹן יְהַב לְכוֹן סִימָּא בְּטוֹעֲנֵיכוֹן כַּסְפְּכוֹן אֲתָא לְוָתִי וְאַפֵּיק לְוָתְהוֹן יָת שִׁמְעוֹן:
@119 וְאָעֵיל גַּבְרָא יָת גֻּבְרַיָּא לְבֵית יוֹסֵף וִיהַב מַיָּא וְאַסְחוֹ רִגְלֵיהוֹן וִיהַב כִּסְּתָא לַחֲמָרֵיהוֹן:
@120 וְאַתְקִינוּ יָת תִּקְרֻבְתָּא עַד דְּעַל יוֹסֵף בְּשֵׁירוּתָא אֲרֵי שְׁמָעוּ אֲרֵי תַמָּן יֵיכְלוּן לַחֲמָא:
@121 וְעַל יוֹסֵף לְבֵיתָא וְאַיְתִיאוּ לֵהּ יָת תִּקְרֻבְתָּא דִּי בִידֵיהוֹן לְבֵיתָא וּסְגִידוּ לֵהּ לְאַרְעָא:
@122 וּשְׁאֵיל לְהוֹן לִשְׁלַם וַאֲמַר הַשְׁלַם אֲבוּכוֹן סָבָא דִּי אֲמַרְתּוּן הַעַד כְּעַן קַיָּם:
@123 וַאֲמָרוּ שְׁלַם לְעַבְדָךְ לְאָבוּנָא עַד כְּעַן קַיָּם וּכְרָעוּ וּסְגִידוּ:
@124 וּזְקַף עֵינוֹהִי וַחֲזָא יָת בִּנְיָמִין אֲחוּהִי בַּר אִמֵּהּ וַאֲמַר הָדֵין אֲחוּכוֹן זְעֵירָא דִּי אֲמַרְתּוּן לִי וַאֲמַר מִן קֳדָם יְיָ יִתְרַחַם עֲלָךְ בְּרִי:
@125 וְאוֹחִי יוֹסֵף אֲרֵי אִתְגּוֹלְלוּ רַחֲמוֹהִי עַל אֲחוּהִי וּבְעָא לְמִבְכֵּי וְעַל לְאִדְרוֹן בֵּית מִשְׁכְּבָא וּבְכָא תַמָּן:
@126 וְאַסְחֵי אַפּוֹהִי וּנְפָק וְאִתְחַסִּין וַאֲמַר שַׁווּ לַחֲמָא:
@127 וְשַׁוִּיאוּ לֵהּ בִּלְחוֹדוֹהִי וּלְהוֹן בִּלְחוֹדֵיהוֹן וּלְמִצְרָאֵי דְּאָכְלִין עִמֵּהּ בִּלְחוֹדֵיהוֹן אֲרֵי לָא יָכְלִין מִצְרָאֵי לְמֵיכַל עִם עִבְרָאֵי לַחְמָא אֲרֵי בְעִירָא דְּמִצְרָאֵי דָחֲלִין לֵהּ עִבְרָאֵי אָכְלִין:
@128 וְאַסְחָרוּ קֳדָמוֹהִי רַבָּא כְּרַבְיוּתֵהּ וּזְעִירָא כִּזְעֵרוּתֵהּ וּתְמָהוּ גֻּבְרַיָּא גְּבַר לְחַבְרֵהּ:
@129 וּנְטַלּ חֳלָקִין מִן קֳדָמוֹהִי לָקֳדָמֵיהוֹן וּסְגִי חֲלָקָא דְבִנְיָמִן מֵחֳלָקֵי דְכָלְּהוֹן חַמְשָׁא חֳלָקִין וּשְׁתִיאוּ וּרְוִיאוּ עִמֵּהּ:
@130 וּפַקֵּיד יָת דִּי מְמַנָּא עַל בֵּיתֵהּ לְמֵימַר מְלֵי יָת טוֹעֲנֵי גֻּבְרַיָּא עִיבוּרָא כְּמָא דִּי יָכְלִין לְמִטְּעַן וְשַׁוִּי כְסַף גְּבַר בְּפוּם טוֹעֲנֵהּ:
@131 וְיָת כַּלִּידִי כַּלִּידָא דְכַסְפָּא תְּשַׁוֵּי בְּפוּם טוֹעֲנָא דִּזְעֵירָא וְיָת כְּסַף זְבִינוֹהִי וַעֲבַּד כְּפִתְגָּמָא דְּיוֹסֵף דִּי מַלִּיל:
@132 צַפְרָא נְהָר וְגֻבְרַיָּא אִתְפַּטָּרוּ אִנּוּן וַחֲמָרֵיהוֹן:
@133 אִנּוּן נְפָקוּ מִן קַרְתָּא לָא אַרְחִיקוּ וְיוֹסֵף אֲמַר לְדִי מְמַנָּא עַל בֵּיתֵהּ קוּם רְדַף בָּתַר גֻּבְרַיָּא וְתַדְבְּקִנּוּן וְתֵימַר לְהוֹן לְמָה שַׁלֶמְתּוּן בִּישָׁא חֳלָף טַבְתָא:
@134 הֲלָא דֵּין דְּשָׁתֵי רִבּוֹנִי בֵּהּ וְהוּא בָּדָקָא מְבָדֵק בֵּהּ אַבְאֶשְׁתּוּן דִּי עֲבַדְתּוּן:
@135 וְאַדְבֵּיקִנּוּן וּמַלֵּיל עִמְּהוֹן יָת פִּתְגָּמַיָּא הָאִלֵּין:
@136 וַאֲמָרוּ לֵהּ לְמָה יְמַלֵּל רִבּוֹנִי כְּפִתְגָּמַיָּא הָאִלֵּין חַס לְעַבְדָּיךְ מִלְּמֶעְבַּד כְּפִתְגָּמָא הָדֵין:
@137 הָא כַסְפָּא דִּי אַשְׁכַּחְנָא בְּפוּם טּוֹעֲנָנָא אֲתֵיבְנוֹהִי לָךְ מֵאַרְעָא דִּכְנָעַן וְאֶכְדֵּין נִגְנוּב מִבֵּית רִבּוֹנָךְ כַּסְפָּא אוֹ דַּהֲבָא (מָנִין דִּכְסַף אוֹ מָנִין דִּדְהָב):
@138 דִּי יִשְׁתְּכַח עִמֵּהּ מֵעַבְדָיךְ וּמִית וְאַף אַנַחְנָא נְהֵי לְרִבּוֹנִי לְעַבְדִין:
@139 וַאֲמַר אַף כְּעַן כְּפִתְגָּמֵיכוֹן כֶּן הוּא דִּי יִשְׁתְּכַח עִמֵּהּ יְהֵי לִי עַבְדָּא וְאַתּוּן תְּהוֹן זַכָּאִין:
@140 וְאוֹחִיאוּ וְאוֹחִיתוּ גְּבַר יָת טּוֹעֲנֵהּ לְאַרְעָא וּפְתָחוּ גְּבַר טוֹעֲנֵהּ:
@141 וּבְלַשׁ בְּרַבָּא שָׁרֵי וּבִזְעֵירָא שֵׁצִי וְאִשְׁתְּכַח כַּלִּידָא בְּטוֹעֲנָא דְבִנְיָמִן:
@142 וּבְזָעוּ לְבוּשֵׁיהוֹן וּרְמוֹ גְּבַר עַל חֲמָרֵהּ וְתָבוּ לְקַרְתָּא:
@143 וְעַל יְהוּדָּה וַאֲחוֹהִי לְבֵית יוֹסֵף וְהוּא עַד כְּעַן תַּמָּן וּנְפָלוּ קֳדָמוֹהִי לְאַרְעָא:
@144 וַאֲמַר לְהוֹן יוֹסֵף מָה עוֹבָדָא הָדֵין דִּי עֲבַדְתּוּן הֲלָא יְדַּעְתּוּן אֲרֵי בָדָקָא מְבָדֵק גַּבְרָא דִּי כְוָתִי:
@145 וַאֲמַר יְהוּדָה מַה נֵּימַר לְרִבּוֹנִי מַה נְּמַלֵּל וּמַה נִזְכֵּי מִן קֳדָם יְיָ אִשְׁתְּכַח יָת חוֹבָא דְעַבְדָּיךְ הָא אֲנַחְנָא עַבְדִּין לְרִבּוֹנִי אַף אֲנַחְנָא אַף דְּאִשְׁתְּכַח כַּלִּידָא בִּידֵהּ:
@146 וַאֲמַר חַס לִי מִלְּמֶעְבַּד דָּא גַּבְרָא דִּי אִשְׁתְּכַח כַּלִּידָא בִּידֵהּ הוּא יְהֵי לִי עַבְדָּא וְאַתּוּן סָקוֹ לִשְׁלַם לְוַת אֲבוּכוֹן: ססס:

@1 **ויהי מקץ.** כתרגומו מסוף, וכל לשון קץ סוף הוא: **על היאר.** כל שאר נהרות אינם קרויין יאורים חוץ מנילוס, מפני שכל הארץ עשוים יאורים יאורים בידי אדם ונילוס עולה בתוכם ומשקה אותם, לפי שאין גשמים יורדין במצרים תדיר כשאר ארצות:
@2 **יפות מראה.** סימן הוא לימי שובע, שהבריות נראות יפות זו לזו, שאין עין בריה צרה בחברתה: **באחו.** באגם, מריש''ק בלע''ז , כמו (איוב ח יא) ישגא אחו:
@3 **ודקות בשר.** טינבי''ש בלע''ז , לשון דק:
@4 **ותאכלנה.** סימן שתהא כל שמחת השובע נשכחת בימי הרעב:
@5 **בקנה אחד.** טודי''ל בלע''ז : **בריאות.** שייני''ש בלע''ז :
@6 **ושדופת.** השלידי''ש בלע''ז ושקיפן קדום, חבוטות לשון משקוף החבוט תמיד על ידי הדלת המכה עליו: **קדים.** רוח מזרחית שקורין ביש''א :
@7 **הבריאות.** שייני ''ש בלע''ז : **והנה חלום.** והנה נשלם חלום שלם לפניו והצרך לפותרים:
@8 **ותפעם רוחו.** ומטרפא רוחה מקשקשת בתוכו כפעמון. ובנבוכדנצר הוא אומר (דניאל ב א) ותתפעם רוחו, לפי שהיו שם שתי פעימות שכחת החלום והעלמת פתרונו: **חרטמי.** הנחרים בטימי מתים, ששואלים בעצמות. טימי, הן עצמות בלשון ארמי, ובמשנה בית שהוא מלא טמיא, מלא עצמות: **ואין פותר אותם לפרעה.** פותרים היו אותם, אבל לא לפרעה, שלא היה קולן נכנס באזניו, ולא היה לו קורת רוח בפתרונם, שהיו אומרים שבע בנות אתה מוליד, שבע בנות אתה קובר:
@11 **איש כפתרון חלומו.** חלום הראוי לפתרון שנפתר לו ודומה לו:
@12 **נער עברי עבד.** ארורים הרשעים שאין טובתם שלמה. מזכירו בלשון בזיון: **נער.** שוטה ואין ראוי לגדלה: **עברי.** אפילו לשוננו אינו מכיר: **עבד.** וכתוב בנמוסי מצרים שאין עבד מולך ולא לובש בגדי שרים: **איש כחלומו.** לפי החלום וקרוב לענינו:
@13 **השיב על כני.** מי שבידו להשיב, והוא פרעה הנזכר למעלה, כמו שאמר (לעיל י) פרעה קצף על עבדיו, הרי מקרא קצר ולא פרש מי השיב, לפי שאין צריך לפרש מי השיב, וכן דרך כל מקראות קצרים על מי שעליו לעשות הם סותמים את הדבר:
@14 **מן הבור.** מן בית הסוהר שהוא עשוי כמין גמא, וכן כל בור שבמקרא לשון גמא הוא, ואף אם אין בו מים קרוי בור פוש''א בלע''ז : **ויגלח.** מפני כבוד המלכות:
@15 **תשמע חלום לפתר אתו.** תאזין ותבין חלום לפתר אתו: **תשמע.** לשון הבנה והאזנה, כמו (להלן מב כג) שומע יוסף, (דברים כח מט) אשר לא תשמע לשונו, אינטינדר''א בלע''ז :
@16 **בלעדי.** אין החכמה משלי אלא אלהים יענה, יתן עניה בפי לשלום פרעה:
@19 **דלות.** כחושות, כמו (ש''ב יג ד) מדוע אתה ככה דל, דאמנון: **ורקות בשר.** כל לשון רקות שבמקרא חסרי בשר, ובלע''ז בלושי''ש :
@23 **צנמות.** צונמא בלשון ארמי סלע, הרי הן כעץ בלי לחלוח, וקשות כסלע, ותרגומו נצן לקין, נצן אין בהן אלא הנץ לפי שנתרוקנו מן הזרע:
@26 **שבע שנים' שבע שנים.** כלן אינן אלא שבע, ואשר נשנה החלום פעמים לפי שהדבר מזמן, כמו שפרש לו בסוף (פסוק לב) ועל השנות החלום וגו' . בשבע שנים הטובות נאמר (פסוק כה) הגיד לפרעה, לפי שהיה סמוך, ובשבע שני רעב נאמר (פסוק כח) הראה את פרעה, לפי שהיה הדבר מפלג ורחוק, נופל בו לשון מראה:
@30 **ונשכח כל השבע.** הוא פתרון הבליעה:
@31 **ולא יודע השבע.** הוא פתרון (פסוק כא) ולא נודע כי באו אל קרבנה:
@32 **נכון.** מזמן:
@34 **וחמש.** כתרגומו ויזרזון וכן (שמות יג יח) וחמושים:
@35 **את כל אכל.** שם דבר הוא, לפיכך טעמו באל''ף ונקוד בפתח קטן, ואוכל שהוא פועל, כגון (ויקרא ז כה) כי כל אכל חלב, טעמו למטה בכף ונקוד קמץ קטן: **תחת יד פרעה.** ברשותו ובאוצרותיו:
@36 **והיה האכל.** הצבור כשאר פקדון הגנוז לקיום הארץ:
@38 **הנמצא כזה.** הנשכח כדין, אם נלך ונבקשנו הנמצא כמוהו. הנמצא לשון תמיהה, וכן כל ה''א המשמשת בראש תבה ונקודה בחטף פתח:
@39 **אין נבון וחכם כמוך.** לבקש איש נבון וחכם שאמרת, לא נמצא כמוך:
@40 **ישק.** יתזן, יתפרנס. כל צרכי עמי יהיו נעשים על ידך, כמו (לעיל טו ב) ובן משק ביתי, וכמו (תהלים ב יב) נשקו בר, גרנישו''ן בלע''ז : **רק הכסא.** שיהיו קורין לי מלך: **כסא.** לשון שם המלוכה כמו (מלכים א א לז) ויגדל את כסאו מכסא אדני המלך:
@41 **נתתי אתך.** מניתי יתך, ואף על פי כן לשון נתינה הוא, כמו (דברים כו יט) ולתתך עליון, בין לגדלה בין לשפלות נופל לשון נתינה עליו, כמו (מלאכי ב ט) נתתי אתכם נבזים ושפלים:
@42 **ויסר פרעה את טבעתו.** נתינת טבעת המלך הוא אות למי שנותנה לו להיות שני לו לגדלה: **בגדי שש.** דבר חשיבות הוא במצרים: **רבד.** ענק, ועל שהוא רצוף בטבעות קרוי רביד. וכן (משלי ז טז) רבדתי ערשי, רצפתי ערשי מרצפות. בלשון משנה (מדות א ח) מקף רבדין של אבן, (יומא מג ב) על הרובד שבעזרה, והיא רצפה:
@43 **במרכבת המשנה.** השניה למרכבתו, המהלכת אצל שלו: **אברך.** כתרגומו דין אבא למלכא. רך בלשון ארמי מלך. בהשותפין (בבא בתרא ד א) לא ריכא ולא בר ריכא. ובדברי אגדה דרש ר' יהודה אברך זה יוסף שהוא אב בחכמה ורך בשנים, אמר לו רבי יוסי בן דורמסקית עד מתי אתה מעות עלינו את הכתובים, אין אברך אלא לשון ברכים, שהכל היו נכנסין ויוצאין תחת ידו, כענין שנאמר ונתון אותו וגו' :
@44 **אני פרעה.** שיש יכולת בידי לגזור גזרות על מלכותי, ואני גוזר שלא ירים איש את ידו: **ובלעדיך.** שלא ברשותך. דבר אחר אני פרעה אני אהיה מלך ובלעדיך וגו' וזהו דגמת (פסוק מ) רק הכסא: **את ידו ואת רגלו.** כתרגומו:
@45 **צפנת פענח.** מפרש הצפונות, ואין לפענח דמיון במקרא: **פוטי פרע.** הוא פוטיפר, ונקרא פוטיפרע על שנסתרס מאליו, לפי שלקח את יוסף למשכב זכר:
@47 **ותעש הארץ.** כתרגומו, ואין הלשון נעקר מלשון עשייה: **לקמצים.** קומץ על קומץ, יד על יד היו אוצרים:
@48 **אכל שדה העיר אשר סביבתיה נתן בתוכה.** שכל ארץ וארץ מעמדת פירותיה ונותנין בתבואה מעפר המקום ומעמיד את התבואה מלירקב:
@49 **עד כי חדל לספר.** עד כי חדל לו הסופר לספר, והרי זה מקרא קצר: **כי אין מספר.** לפי שאין מספר, והרי כי משמש בלשון דהא:
@50 **בטרם תבוא שנת הרעב.** מכאן שאסור לאדם לשמש מטתו בשני רעבון:
@55 **ותרעב כל ארץ מצרים.** שהרקיבה תבואתם שאצרו חוץ משל יוסף: **אשר יאמר לכם תעשו.** לפי שהיה יוסף אומר להם שימולו, וכשבאו אצל פרעה ואומרים כך הוא אומר לנו, אמר להם למה לא צברתם בר, והלא הכריז לכם ששני הרעב באים, אמרו לו אספנו הרבה והרקיבה, אמר להם אם כן כל אשר יאמר לכם תעשו, הרי גזר על התבואה והרקיבה, מה אם יגזור עלינו ונמות:
@56 **על כל פני הארץ.** מי הם פני הארץ, אלו העשירים: **את כל אשר בהם.** כתרגומו די בהון עבורא: **וישבר למצרים.** שבר לשון מכר ולשון קנין הוא, כאן משמש לשון מכר, (להלן מג ב) שברו לנו מעט אכל, לשון קנין. ואל תאמר אינו כי אם בתבואה, שאף ביין וחלב מצינו (ישעיה נה א) ולכו שברו בלא כסף ובלא מחיר יין וחלב:
@57 **וכל הארץ באו מצרימה לשבר אל יוסף.** (סרסהו ופרשהו וכל הארץ באו מצרים אל יוסף) . אם תפרשהו כסדרו היה צריך לכתוב לשבור מן יוסף:
@58 **וירא יעקב כי יש שבר במצרים.** ומהיכן ראה, והלא לא ראה אלא שמע, שנאמר (להלן מב ב) הנה שמעתי וגו' , ומהו וירא, ראה באספקלריא של קדש שעדין יש לו שבר סבר במצרים. ולא היתה נבואה ממש להודיעו בפרוש שזה יוסף: **למה תתראו.** למה תראו עצמכם בפני בני ישמעאל ובני עשו כאלו אתם שבעים, שבאותה שעה עדין היה להם תבואה. [ולי נראה כפשוטו למה תתראו, למה יהיו הכל מסתכלין בכם ומתמיהים בכם שאין אתם מבקשים לכם אכל בטרם שיכלה מה שבידכם]. ומפי אחרים שמעתי שהוא לשון כחישה, למה תהיו כחושים ברעב. ודומה לו (משלי יא כה) ומרוה גם הוא יורא:
@59 **רדו שמה.** ולא אמר לכו, רמז למאתים ועשר שנים שנשתעבדו למצרים, כמנין רד''ו:
@60 **וירדו אחי יוסף.** ולא כתב בני יעקב, מלמד שהיו מתחרטים במכירתו ונתנו לבם להתנהג עמו באחוה ולפדותו בכל ממון שיפסקו עליהם: **עשרה.** מה תלמוד לומר, והלא כתיב (פסוק ד) ואת בנימין אחי יוסף לא שלח, אלא לענין האחוה היו חלוקין לעשרה, שלא היתה אהבת כלם ושנאת כלם שוה לו, אבל לענין לשבור בר כלם לב אחד להם:
@61 **פן יקראנו אסון.** ובבית לא יקראנו אסון, אמר רבי אלעזר בן יעקב מכאן שהשטן מקטרג בשעת הסכנה:
@62 **בתוך הבאים.** מטמינין עצמן שלא יכירום, לפי שצוה להם אביהם שלא יתראו כלם בפתח אחד אלא שיכנס כל אחד בפתחו, כדי שלא תשלט בהם עין הרע שכלם נאים וכלם גבורים: [ כי היה הרעב . מוסב על הבאים , כי היה הרעב בארץ כנען והיו באים הרבה שירות משם]:
@63 **וישתחוו לו אפים.** נשתטחו לו על פניהם, וכן כל השתחואה פשוט ידים ורגלים היא:
@64 **ויתנכר אליהם.** נעשה להם כנכרי בדברים, לדבר קשות:
@65 **ויכר יוסף** וגו' **.** לפי שהניחם חתומי זקן: **והם לא הכרהו.** שיצא מאצלם בלא חתימת זקן, ועכשיו בא בחתימת זקן. ומדרש אגדה ויכר יוסף את אחיו כשנמסרו בידו הכיר שהם אחיו ורחם עליהם, והם לא הכירוהו כשנפל בידם לנהוג בו אחוה:
@66 **אשר חלם להם.** עליהם, וידע שנתקימו, שהרי השתחוו לו: **ערות הארץ.** גלוי הארץ, מהיכן היא נוחה לכבש, כמו (ויקרא כ יח) את מקורה הערה, וכמו (יחזקאל טז ז) ערום ועריה. וכן כל ערוה שבמקרא לשון גלוי. ותרגום אנקלוס בדקא דארעא, כמו (מלכים ב' יב ו) בדק הבית, רעוע הבית, אבל לא דקדק לפרשו אחר לשון המקרא:
@67 **לא אדני.** לא תאמר כן, שהרי עבדיך באו לשבר אכל:
@68 **כלנו בני איש אחד נחנו.** נצנצה בהם רוח הקדש וכללוהו עמהם שאף הוא בן אביהם: **כנים.** אמתיים, כמו (שמות י כט) כן דברת, (במדבר כז ז) כן בנות צלפחד דוברות, (ישעיה טז ו) ועברתו לא כן בדיו:
@69 **כי ערות הארץ באתם לראות.** שהרי נכנסתם בעשרה שערי העיר, למה לא נכנסתם בשער אחד:
@70 **ויאמרו שנים עשר עבדיך** וגו' **.** ובשביל אותו אחד שאיננו נתפזרנו בעיר לבקשו:
@71 **הוא אשר דברתי.** הדבר אשר דברתי שאתם מרגלים הוא האמת והנכון, זהו לפי פשוטו. ומדרשו אמר להם ואלו מצאתם אותו ויפסקו עליכם ממון הרבה תפדוהו. אמרו לו הן. אמר להם ואם יאמרו לכם שלא יחזירוהו בשום ממון מה תעשו. אמרו לו לכך באנו, להרוג או להרג, אמר להם הוא אשר דברתי אליכם להרוג בני העיר באתם, מנחש אני בגביע שלי ששנים מכם החריבו כרך גדול של שכם:
@72 **חי פרעה.** אם יחיה פרעה. שהיה נשבע לשקר, היה נשבע בחיי פרעה: **אם תצאו מזה.** מן המקום הזה:
@73 **האמת אתכם.** אם אמת אתכם. לפיכך ה''א נקוד פתח שהוא כמו בלשון תמה. ואם לא תביאוהו, חי פרעה כי מרגלים אתם:
@74 **משמר.** בית האסורים:
@76 **בבית משמרכם.** שאתם אסורים בו עכשיו: **ואתם לכו הביאו.** לבית אביכם: **שבר רעבון בתיכם.** מה שקניתם לרעבון אנשי בתיכם:
@77 **ויאמנו דבריכם.** יתאמתו ויתקימו, כמו (במדבר ה כב) אמן אמן, וכמו (מ''א ח כו) יאמן נא דברך:
@78 **אבל.** כתרגומו בקושטא. וראיתי בבראשית רבה (צא ח) לישנא דרומאה היא אבל, ברם: **באה אלינו.** טעמו בבי''ת, לפי שהוא בלשון עבר שכבר באה, ותרגומו אתת לנא:
@79 **וגם דמו.** אתין וגמין רבויין, דמו וגם דם הזקן:
@80 **והם לא ידעו כי שומע יוסף.** מבין לשונם ובפניו היו מדברים כן: **כי המליץ בינתם.** כי כשהיו מדברים עמו היה המליץ ביניהם, היודע לשון עברי ולשון מצרי, והיה מליץ דבריהם ליוסף ודברי יוסף להם, לכך היו סבורים שאין יוסף מכיר בלשון עברי: **המליץ.** זה מנשה:
@81 **ויסב מעליהם.** נתרחק מעליהם שלא יראוהו בוכה: **ויבך.** לפי ששמע שהיו מתחרטין: **את שמעון.** הוא השליכו לבור, הוא שאמר ללוי (לעיל לז יט) הנה בעל החלומות הלזה בא. דבר אחר נתכון יוסף להפרידו מלוי שמא יתיעצו שניהם להרוג אותו: **ויאסור אותו לעיניהם.** לא אסרו אלא לעיניהם, וכיון שיצאו הוציאו והאכילו והשקהו:
@84 **ויפתח האחד.** הוא לוי שנשאר יחיד משמעון בן זוגו: **במלון.** במקום שלנו בלילה: **אמתחתו.** הוא שק:
@85 **וגם הנה באמתחתי.** גם הכסף בו עם התבואה: **מה זאת עשה אלהים לנו.** להביאנו לידי עלילה זו שלא הושב אלא להתעולל עלינו:
@91 **ואת הארץ תסחרו.** תסובבו. וכל לשון סוחרים וסחורה על שם שמחזרים וסובבים אחר פרקמטיא:
@92 **צרור כספו.** קשר כספו:
@93 **אתי שכלתם.** מלמד שחשדן שמא הרגוהו או מכרוהו כיוסף: **שכלתם.** כל מי שבניו אבודים קרוי שכול:
@95 **לא ירד בני עמכם.** לא קבל דבריו של ראובן. אמר בכור שוטה הוא זה, הוא אומר להמית בניו, וכי בניו הם ולא בני:
@97 **כאשר כלו לאכל.** יהודה אמר להם המתינו לזקן עד שתכלה פת מן הבית: **כאשר כלו.** כד שציאו. והמתרגם כד ספיקו, טועה כאשר כלו הגמלים לשתות מתרגם כד ספיקו כששתו די ספוקם הוא גמר שתיתם. אבל זה כאשר כלו לאכול, כאשר תם האכל הוא, ומתרגמינן כד שציאו:
@98 **העד העד.** לשון התראה, שסתם התראה מתרה בו בפני עדים, וכן (ירמיהו יא ז) העדתי באבותיכם, (שמות יט כא) רד העד בעם: **לא תראו פני בלתי אחיכם אתכם.** לא תראוני בלא אחיכם אתכם. ואנקלוס תרגם אלהין כד אחוכון עמכון, ישב באור הדבר על אפנו ולא דקדק לתרגם אחר לשון המקרא:
@102 **לנו ולמולדתנו.** למשפחותינו, ומדרשו אפילו עצי עריסותינו גלה לנו: **ונגד לו.** שיש לנו אב ואח: **על פי הדברים האלה.** על פי שאלותיו אשר שאל הזקקנו להגיד: **כי יאמר.** אשר יאמר, כי משמש בלשון אם, ואם משמש בלשון אשר. הרי זה שמוש אחד מארבע לשונותיו שמשמש כי, והוא אם, שהרי כי זה כמו אם, כמו עד אם דברתי דברי (כד לג) :
@103 **ונחיה.** נצנצה בו רוח הקדש, על ידי הליכה זו תחי רוחך שנאמר (מה כז) ותחי רוח יעקב אביהם: **ולא נמות.** ברעב. בנימין ספק יתפש ספק לא יתפש, ואנו כלנו מתים ברעב אם לא נלך, מוטב שתניח את הספק ותתפוש את הודאי:
@104 **והצגתיו לפניך.** שלא אביאנו אליך מת כי אם חי: **וחטאתי לך כל הימים.** לעולם הבא:
@105 **לולא התמהמהנו.** על ידך, כבר היינו שבים עם שמעון ולא נצטערת כל הימים הללו:
@106 **אפוא.** כל לשון אפוא לשון יתר הוא לתקון מלה בלשון עברי, אם כן אזדקק לעשות שאשלחנו עמכם, צריך אני לחזור ולבקש איה פה תקנה ועצה להשיאכם, ואומר אני זאת עשו: **מזמרת הארץ.** מתרגם מדמשבח בארעא שהכל מזמרים עליו כשהוא בא לעולם: **נכאת.** שעוה: **בטנים.** לא ידעתי מה הם ובפרושי א' ב' של רבי מכיר ראיתי פישיטצי''ש [פיסטוקים] ודומה לי שהם אפרסקין:
@107 **וכסף משנה.** פי שנים כראשון: **קחו בידכם.** לשבור אוכל, שמא הוקר השער: **אולי משגה הוא.** שמא הממנה על הבית שכחו שוגג:
@109 **ואל שדי.** מעתה אינכם חסרים כלום אלא תפלה, הריני מתפלל עליכם: **ואל שדי.** שדי בנתינת רחמיו, וכדי היכולת בידו לתן, יתן לכם רחמים, זהו פשוטו. ומדרשו מי שאמר לעולם די יאמר די לצרותי, שלא שקטתי מנעורי, צרת לבן, צרת עשו, צרת רחל, צרת דינה, צרת יוסף, צרת שמעון, צרת בנימין: **ושלח לכם.** ויפטר לכון, תרגומו, יפטרנו מאסוריו, לשון (שמות כא כו) לחפשי ישלחנו, ואינו נופל בתרגום לשון וישלח, שהרי לשם הם הולכים אצלו: **את אחיכם.** זה שמעון: **אחר.** רוח הקדש נזרקה בו, לרבות יוסף: **ואני.** עד שובכם אהיה שכול מספק: **כאשר שכלתי.** מיוסף ומשמעון: **שכלתי.** מבנימין:
@110 **ואת בנימין.** מתרגמינן ודברו ית בנימין, לפי שאין לקיחת הכסף ולקיחת האדם שוה בלשון ארמי, בדבר הנקח ביד מתורגם ונסיב, ודבר הנקח בהנהגת דברים מתרגמינן ודבר:
@111 **וטבוח טבח והכן.** כמו ולטבוח טבח ולהכין, ואין טבוח לשון צווי שהיה לו לומר וטבח: **בצהרים.** זה מתורגם בשירותא, שהוא לשון סעודה ראשונה בלשון ארמי, ובלע''ז דישני''ר [ארוחת צהרים], ויש הרבה בתלמוד (תענית יא ב) שדא לכלבא שירותיה, (ברכות לט ב) בצע אכולא שירותיה. אבל כל תרגום של צהרים טיהרא:
@113 **וייראו האנשים.** כתוב בשני יודי''ן ותרגומו ודחילו: **כי הובאו בית יוסף.** ואין דרך שאר הבאים לשבור בר ללון בבית יוסף, כי אם בפנדקאות שבעיר. וייראו שאין זה אלא לאספם אל משמר: **אנחנו מובאים.** אל תוך הבית הזה: **להתגולל.** להיות מתגלגלת עלינו עלילת הכסף ולהיותה נופלת עלינו. ואונקלוס שתרגם ולאסתקפא עלנא, הוא לשון להתעולל, כדמתרגמינן (דברים כב יד) עלילת דברים תסקופי מלין, ולא תרגמו אחר לשון המקרא, ולהתגלל שתרגם לאתרברבא הוא לשון (קהלת יב ו) גלת הזהב, (נחום ב ח) והצב גלתה העלתה, שהוא לשון מלכות:
@115 **בי אדני.** לשון בעיא ותחנונים הוא, ובלשון ארמי בייא בייא: **ירד ירדנו.** ירידה היא לנו, רגילים היינו לפרנס אחרים, עכשיו אנו צריכים לך:
@118 **אלהיכם.** בזכותכם, ואם אין זכותכם כדאי, ואלהי אביכם, בזכות אביכם נתן לכם מטמון:
@119 **ויבא האיש.** הבאה אחר הבאה, לפי שהיו דוחפים אותו לחוץ עד שדברו אליו פתח הבית, ומשאמר להם (פסוק כג) שלום לכם, נמשכו ובאו אחריו:
@120 **ויכינו.** הזמינו, עטרוה בכלים נאים:
@121 **הביתה.** מפרזדור לטרקלין:
@123 **ויקדו וישתחוו.** על שאילת שלום. קידה כפיפת קדקד, השתחואה משתטח לארץ:
@124 **אלהים יחנך בני.** בשאר שבטים שמענו חנינה (לעיל לג ה) אשר חנן אלהים את עבדך, ובנימין עדיין לא נלד, לכך ברכו יוסף בחנינה:
@125 **כי נכמרו רחמיו.** שאלו יש לך אח מאם, אמר לו אח היה לי ואיני יודע היכן הוא. יש לך בנים, אמר לו יש לי עשרה, אמר לו ומה שמם, אמר לו (להלן מו כא) בלע ובכר וגו' , אמר לו מה טיבן של שמות הללו, אמר לו כלם על שם אחי והצרות אשר מצאוהו, בלע שנבלע בין האמות. בכר שהיה בכור לאמי. אשבל ששבאו אל. גרא שנתגייר באכסניא. ונעמן, שהיה נעים ביותר. אחי וראש אחי היה וראשי היה. מפים מפי אביו למד. וחפים שלא ראה חפתי ולא ראיתי אני חפתו. וארד שירד לבין האמות, כדאיתא במסכת סוטה (לו ב) מיד נכמרו רחמיו: **נכמרו.** נתחממו, ובלשון משנה (ב''מ עד א) על הכמר של זיתים, ובלשון ארמי מכמר בשרא, ובמקרא (איכה ה י) עורנו כתנור נכמרו, נתחממו ונקמטו קמטים קמטים מפני זלעפות רעב. כן דרך כל עור כשמחממין אותו נקמט וכווץ:
@126 **ויתאפק.** נתאמץ. והוא לשון (איוב יב כא) ומזיח אפיקים רפה, וכן (איוב מא ז) אפיקי מגנים, חוזק:
@127 **כי תועבה הוא.** דבר שנאוי הוא למצרים לאכול את העברים, ואונקלוס נתן טעם לדבר:
@128 **הבכור כבכורתו.** מכה בגביע וקורא ראובן שמעון לוי ויהודה יששכר וזבולון, בני אם אחת, הסבו כסדר הזה שהוא סדר תולדותיכם וכן כלם, כיון שהגיע לבנימין אמר זה אין לו אם ואני אין לי אם ישב אצלי:
@129 **משאת.** מנות: **חמש ידות.** חלקו עם אחיו ומשאת יוסף ואסנת ומנשה ואפרים: **וישכרו עמו.** ומיום שמכרוהו לא שתו יין, ולא הוא שתה יין, ואותו היום שתו
@131 **גביע.** כוס ארוך, וקורין לו מדירנ''א בלע''ז :
@136 **חלילה לעבדיך.** חלין הוא לנו, לשון גנאי. ותרגום חס לעבדיך, חס מאת הקדוש ברוך הוא יהי עלינו מעשות זאת והרבה חס ושלום יש בתלמוד בלשון הזה:
@137 **הן כסף אשר מצאנו.** זה אחד מעשרה קל וחמר האמורים בתורה. וכלן מנויין בבר' רבה:
@139 **גם עתה כדבריכם.** אף זו מן הדין, אמת כדבריכם כן הוא שכלכם חיבים בדבר, עשרה שנמצאת גנבה ביד אחד מהם כלם נתפשים, אבל אני אעשה לכם לפנים משורת הדין, אשר ימצא אתו יהיה לי עבד:
@141 **בגדול החל.** שלא ירגישו בו שהיה יודע היכן הוא:
@142 **ויעמס איש על חמרו.** בעלי זרוע היו ולא הצרכו לסיע זה את זה לטעון: **וישבו העירה.** מטרפולין היתה והוא אומר העירה, עיר כל שהיא, אלא שלא היתה חשובה בעיניהם אלא כעיר בינונית של עשרה בני אדם לענין המלחמה:
@143 **עודנו שם.** שהיה ממתין להם:
@144 **הלוא ידעתם כי נחש ינחש** וגו' **.** הלא ידעתם כי איש חשוב כמוני יודע לנחש ולדעת מדעת ומסברא ובינה כי אתם גנבתם הגביע:
@145 **האלהים מצא.** יודעים אנו שלא סרחנו, אבל מאת הקדוש ברוך הוא נהיתה להביא לנו זאת. מצא בעל חוב מקום לגבות שטר חובו: **ומה נצטדק.** לשון צדק, וכן כל תבה שתחלת יסודה צד''י והיא באה לדבר בלשון מתפעל או נתפעל נותן טי''ת במקום תי''ו, ואינה נתנת לפני אות ראשונה של יסוד התבה אלא באמצע אותיות העקר, כגון נצטדק מגזרת צדק, (דניאל ד ל) ויצטבע מגזרת צבע, (יהושע ט ד) ויצטירו מגזרת (משלי יג יז) ציר אמונים, (יהושע ט יב) הצטידנו מגזרת (לעיל מב כה) צדה לדרך. ותיבה שתחלתה סמ''ך או שי''ן כשהיא מתפעלת התי''ו מפרדת את אותיות העקר, כגון (קהלת יב ה) ויסתבל החגב, מגזרת סבל, (דניאל ז ח) משתכל הוית בקרניא, (מיכה ו טז) וישתמר חקות עמרי, מגזרת שמר, (ישעיה נט טו) וסר מרע משתולל, מגזרת (איוב יב יז) מוליך יועצים שולל, (שמות ט יז) מסתולל בעמי, מגזרת (ירמיה יח טו) דרך לא סלולה:

@1 **ויהי מקץ**. טעם אומרו לשון צער. כי עתה יתחיל לסובב סיבת גלות מצרים. והגם שהגלות כבר נגזרה גזירתו משנים קדמוניות, הלא אמרו רבותינו כי לא נגזר שיהיה במצרים שהוא כור הברזל, וכמו שכתבו התוס' במס' שבת (י:) וכמו שכתב הראב''ד (פ''ו הל' תשובה) כי המצרים הוסיפו לצער יותר ממה שאמר הכתוב ועבדום וענו וגו':
@1 **עוד** אמר לשון צער לצד בשורת רעב כי הקב''ה כביכול לו צר בצרת עולמו, וצא ולמד ממה שדרשו ז''ל (מגילה י:) בפסוק (שמות יד כ) ולא קרב זה אל זה וגו':
@1 **עוד** ירמוז לצערו של אותו צדיק שנתעכב עד ששלמו ב' שנים אחר חלומו של שר המשקים כי אז היה לו לצאת כאומרם ז''ל (ב''ר פ' פ''ט) וז''ל בשביל שאמר כי אם זכרתני והזכרתני ניתוספו ב' שנים, הרי שהוסיפו לו ב' שנים בצער, ותמצא שאמרו ז''ל (שם) ויהי מקץ קץ שם לחושך. ולפי זה יכוין על זה הדרך ויהי מסיבת קץ שהוא יצר הרע שנקרא קץ כל בשר והוא סיבה לצערו של צדיק שנתים ימים. ובזה הרווחנו גם כן תחלת זה החשבון של שנתים שהוא לחלומו של שר המשקים שהיה זמן זכירת יוסף לטובה, וטעם ב' שנים בשביל שאמר זכרתני והזכרתני כנגד כל זכירה מנע ה' זכרונו בראש השנה שהוא זמן הזכרון:
@1 **עוד** ירמוז באומרו **מקץ שנתים** לומר שהיה בזמן עצמו שחלמו שר המשקים ושר האופים שהוא זמן שהחלום יגיד דבר צודק ולא ידבר שוא:
@1 **ופרעה חולם**. הנה לצד שהיא תחלת ההודעה היה צריך לומר חולם פרעה או ויחלום פרעה. אכן הכתוב מוסב אל ענין ראשון שספר בפרשה שקדמה חלומו של שר המשקים לענינו הוסיף לומר ופרעה גם כן חולם. והכוונה בזה כי אם שר המשקים לא רצה לזוכרו על ידי חלומו עשה ה' שגם פרעה יחלום ובזה נתחייב בעל כורחו לזוכרו. ושיעור הכתוב הוא על זה הדרך ולא זכר שר המשקים ויהי מקץ וגו' ופרעה גם הוא חולם וגו' וידבר שר המשקים בעל כרחו לאמר וגו' ושם אתנו וגו' ויפתר לנו וגו':
@1 **עוד** אפשר שיכוין לומר כי שנתים ימים ופרעה חולם בתמידות חלום זה אלא שלא היה יודע שחלם ולסוף שנתים חלם ולא שכח:
@1 **עוד** ירצה באומרו **ופרעה חולם** לומר שגם פרעה עצמו הרגיש בחלומו כי היה חולם חלום לצד ראותו דברים מופלאים כאשר אבאר הרגיש כי אין זה מהדברים ההווים בעולם ואין זה אלא חלום וכוונת הכתוב בהודעה זו היא להגיד סימני החלום אשר יצטדק, והוא כאשר ירגיש האדם בחלום כי הוא שלם בדעתו להבחין דבר עד שישכיל לדעת דברים שלא יתכן היות בהקיץ וירגיש כי הוא חולם זה יגיד כי אין חלומו בלבול הדעת וערבוב השכל ורוחות יתעללו בו אלא מודיעים אותו עליונים למעלה עתידות:
@2 **מן היאור עולות וגו'**. היה לו לומר **עולות שבעפרות מן היאור** כי מן הראוי יזכיר העולה ואח''כ מקום שעולה משם. ואולי שיכוין לומר כי כל הוייתן היתה מן היאור. ולזה הקדים המהווה ואחר כך המתהווה ממנו, ולזה אם היה אומר והנה שבע פרות עולות מן היאור יהיה הנשמע כי הפרות עברו דרך היאור ועלו ממנו ולא מהיאור נמצאו, לזה אמר מן היאור עולות שבע פרות לומר שממנו נמצאו, ומזה הרגיש גם כן כי הוא חולם חלום וכמו שפירשתי בפסוק ופרעה חולם (א'). וטעם שהראוהו מראה זה להגיד כי מהיאור עצמו יתהוו ב' הדמיונות, והוא שפתר יוסף שהם שבע שני שבע ושבע שני רעב ושניהם הם מתהוים מהיאור עצמו אם יעלה או לא יעלה ולזה ראה בחלום כי הפרות הוויתן היתה מהיאור:
@3 **עולות אחריהן מן היאור**. פירוש על אופן שכתבנו שכל מציאותם מן היאור היה. והגם שלא אמר מן היאור עולות כמו שאמר בראשונות סמך על אומרו תיבת אחריהן שהוא כסדר הראשון שמהיאור הוא התחלת הוויתן:
@7 **וייקץ וגו' והנה חלום**. אולי כי בחלום השבלים לא הכיר בו בחלומו כי היה חולם והיה חושב שהיה בהקיץ לרוב בהירות הדבר והכירו בלא בלבול כדרך החולם, אלא אחר שעמד משנתו אז הכיר למפרע כי היה חולם, והוא אומרו **וייקץ פרעה** והנה מצא עצמו כי חלום היו הדברים ולא בהקיץ:
@8 **ואין פותר אותם וגו'**. אמר **אותם** לצד שהיו ב' חלומות, והגם שאמר הכתוב לשון יחיד את חלומו, כשבא להודיע כי לא מצא פותר דקדק לומר אותם שכל ב' החלומות אין פותר להם:
@8 **ואומרו לפרעה** ללא צורך, נראה לומר שיכוין הכתוב באומרו לפרעה כי דבר ידוע הוא כי שם פרעה אינו שם העצם אלא שם המלכות, ולזה תמצא שדבר אליו שר המשקים פרעה קצף וגו' ואין מהמוסר שיזכיר שם המלך בפניו כסדר זה אלא ודאי שהוא שם המלוכה, וכן אמרו ז''ל, (רש''י תהלים ל''ד) ומעתה בא לתת טעם למה לא נתקבל פתרונם אצלו, כי לצד שהחלום היה למלך ואמרו ז''ל (ב''ר פ' פ''ט) כי חלומות המלכים יגידו דברים הנוגעים לכללות המלכות, והדעת כן נותנת, והם לא היו פותרים פתרון שנוגע למלכות אלא פתרונים של הדיוטות. ורז''ל (שם) אמרו לפרעה שלא היה מתקבל פתרונם לו, ודבריהם היו נשמעים אם היה אומד ואין פותר וגו' לו:
@9 **וידבר שר וגו' לאמר וגו'**. טעם אומרו **לאמר**, גם אומרו **את** ולא אמר אל. ואולי שלא דיבר אליו לנוכח אלא לחכמי מצרים לאמר לפרעה, ולזה תמצא שכל דבריו הם דרך נסתר לא לנוכח, פרעה קצף ויתן לשון נסתר:
@9 **עוד** ירצה באומרו **לאמר את חטאי** על זה הדרך שלא תחשוב שאני זוכר את אשר עבר עלי מיסורי המלך אלא אדרבה אני אומר פחיתותי וגרעוני כי אני הוא החוטא, והוא אומרו לאמר את חטאי וגו'. ודקדק לומר **היום** כי הוא עת הצורך כי זולת זה היה מעלים זכרון מעשיו הפחותים, גם בזה נתן טעם למה שלא הודיע הדבר מקודם כחיוב המוטל על קרובי המלך להודיע דבר חדש כזה, כי לא היה להזכיר עוד שגיונו, ואמר **חטאי** לשון רבים לומר כי חשוב בעיניו את אשר כבר עשוהו לחטאים רבים. או אולי שנתכוין לרמוז גם לחטא זה שמנע ההודעה עד עתה לזה **אמר** לשון רבים חטאי:
@15 **ופותר אין אותו**. פירוש שהיו לו פותרים אלא שלא היה צודק החלום על פי הפותרים, והוא אומרו **ופותר אין אותו** והכוונה בזה שיפתור פתרון שיצטדק עם החלום:
@15 **ואני שמעתי וגו'**. צריך לדעת אומרו. **לאמר**. עוד אומרו **תשמע** פשיטא שלא יפתור קודם שישמע והיה לו לומר שמעתי עליך פותר חלום:
@15 **אכן** הכוונה היא שנתחכם פרעה לחייב יוסף לפתור החלום מבלי תת אמתלאות, ובא בטענה לומר כי הוא יוסף פיו העידו כי הוא פותר חלומות, ומעתה לא ימנע מחלוקה או יפתור חלומו של פרעה או יתחייב על אשר רימה בני אדם שהוא פותר ואין בפיהו נכונה, והוא אומרו **ואני שמעתי עליך לאמר** פידוש שאתה אומר תשמע חלום לפתור אותו, כמו שכן היה אחר האמת שאמר לשר המשקים ושר האופים (מ' ז') ספרו נא לי וגו', ומן הסתם שר המשקים הודיע הדברים כמות שהם לפרעה או פרעה בחן כי לא יגידו שריו חלומות לנער עברי עבד אם לא ששאל הוא להגידו, ומעתה יתחייב לפתור חלומו של פרעה לצדק דבריו:
@16 **ויען יוסף לאמר וגו'**. פי' השיבו למה שטען בתיבת **לאמר** כי הוא אומר לשמוע חלום לפתור, **בלעדי** לא היו כן הדברים, ומה שאמר הוא כי אלהים ימציא פתרונים לחלומות על יד בני אדם כמו שמצינו שכן אמר יוסף לשר המשקים ושר האופים (שם) הלא לאלהים פתרונים פי' לא יחסרו הפתרונים ואמר ספרו לי אולי ימצא פתרון ולעולם אינו מייחד עצמו לומר כי הוא מפשר חלומות, וכמו כן הוא אומר לו **אלהים יענה** וגו'. והוצרך לומר יענה שלום, נתכוון לומר לו שלא יקפיד אם יהיה פתרון החלום מגיד רעתו כי מה' מענה דבר ולא יקפיד לומר כי החלומות הולכים אחר הפה, ונתן טעם באומרו שלום פרעה כי המלך ישתנה בדבר זה, ולזה אם יגיד רע לא ממנו יצאו הדברים, וכמו כן הוא אומרו עתה **אלהים יענה אתשלום פרעה**:
@16 **עוד** ירצה באומרו **אלהים יענה** כי אין סדר אופן פתרונו כסדר פתרון בר הדיא (ברכות נו.) וכיוצא בו שיטה החלום לאשר יחפוץ אלא אמיתות משמעות הדברים, ולזה אמר אלהים וגו':
@25 **את אשר האלהים וגו'**. יתבאר על דרך אומרם ז''ל (ברכות נה.) ג' דברים הקב''ה מכריז עליהן והם שבע ורעב ופרנם, והוא אומרו את אשר האלהים עושה בכבודו שלא על ידי שליח הגיד וגו', שבע אלו שני שבע. רעב אלו שני רעב. פרנס ירא פרעה איש וגו'. והגם שלא אמר לו מי זה האיש, אף על פי כן אחר האמת תמך גורלו במה שמנע הפתרון מכל חכמיו וגילה לו את יוסף על ידי שר המשקים שספר לו העובר עליו ונתגלגלו הדברים ונתגלה לו יוסף וישיתהו על ארץ מצרים. ואומרו **הגיד לפרעה** פי' שיש סיפוק בידו לעשות תיקון כמו שאמר לבסוף (פסוק ל''ג) ירא פרעה וגו' וחמש וגו':
@27 **יהיו שבע שני רעב**. טעם שלא אמר כן על שבע שני שבע, לצד שגם בימים ההם היו שני שבע ואין דבר חדש כל כך אלא שיתרבה השבע כאומרו (כ''ט) שבע גדול שהחידוש הוא היות השבע גדול, לזה לא אמר אלא דבר חדש מופלא שהוא שני רעב:
@27 **עוד** נראה כי לצד שהשבע אינו אלא לצורך תיקון שני רעב כמו שגילה לבסוף שצוה ללקט תבואות שני שבע לשני רעב, לזה לא הזכיר אלא שני הרעב כי הוא עיקר הודעת החלום אליו:
@29 **הנה שבע שנים וגו'**. דקדק לומר **בכל ארץ מצרים** ב' פעמים ולא אמר בארץ סתם כמו שאמר בסמוך, לומר כי השבע אינו אלא בארץ מצרים אבל הרעב הוא בכל העולם, ולזה כשאמר וכלה הרעב לא **אמר** ארץ מצרים בלבד אלא את הארץ בין ארץ מצרים בין שאר הארצות, וכמו שכן היה דכתיב (פסוק נ''ו) והרעב היה על כל פני הארץ, ובשבע אמר הכתוב (נ''ג) ותכלינה שבע שני השבע אשר היה בארץ מצרים הרי זה מגיד כי לא היה שבע אלא בארץ מצרים שאם לא כן לא היה צריך לומר אשר היה בארץ מצרים, והודעת דבר זה ליוסף היתה ממה שראה כי הפרות היו כל כך דקות ורעות מזה דן שאם היה השובע בעולם לא היו במצרים כל כך בשבע שני הרעב כי יביאו לחם משאר הארצות אלא ודאי שהרעב הוא בכל העולם ובזה אין מפלט להם, והשבע אין לו ממה להוכיח כי יהיה בכל הארצות:
@32 **ועל השנות וגו'**. רמז לב' דברים על הכפל ועל השינוי שלא בא החלום ב' כחלום ראשון שבע פרות וגו' שאז יחשוב כי דמיון הראשון עשה רושם בדעתו ועלה על משכבו ב' פעמים, ולכן בא החלום בסרר חדש שבע שבלים וגו' הרי זה בא ללמד כי נכון הדבר ומעם האלהים בא אליו החלום ולא דמיון כוזב:
@32 **ואומרו וממהר האלהים וגו'**. פירוש מה שבא החלום כפול בלילה אחת ולא בא בב' זמנים מרוחקים לומר אליו שהזמן קרוב הוא ולא לזמנים רחוקים יגיד:
@33 **ועתה ירא וגו'**. טעם יוסף שנעשה יועץ למלך והוא לא בקש ממנו אלא פתרון החלום, כי בא לתת לו טעם אשר הראהו ה' את אשר הוא עושה כי הוא כדי שיפקד פקידים וגו'. עוד להיות שהראוהו בחלום שבלעו הפרות הרקות לפרות הבריאות זה יגיד כי יתפרנסו שני רעב משני שבע, ולזה אמר **ירא פרעה** וגו':
@33 **איש נבון וחכם**. לדעת אופן אוצרות התבואה לבל תרקב וזה מהתבונה. ואומרו **וחכם** שיודע כלליות החכמות לדעת חכמת התשבורת וההנדסה והמספר, והקדים נבון כי הוא דבר המעכב יותר כדי שתתקיים התבואה:
@34 **יעשה פרעה**. כוונת הדברים הם כי השכיל יוסף שטעם החלום הוא לצד כי ה' מביא שבע שני שבע בשופע יותר על שאר השנים כדי שתהיה התבואה לשבע שני רעב וזולת הודעת החלום כשתבוא תבואת שנה ראשונה מרווחת אז כשתבוא שנה שניה יתרשלו זורעי תבואה כי יאמרו הרי עשתה תבואה שנה ראשונה לשלש שנים, וגם לצד הריבוי תזול התבואה ויתעצלו מטרוח בחרישה וזריעה ומכשיריה, וגם הזורעים בשנה שניה כשיתברך יוסיפו עוד להתעצל מלזרוע עוד, ומה גם בעבור שלש או ארבע שנים הן לא יעשה עבודה בשדה לזרוע ולחרוש, אשר על כן הודיע אלהים כי מה שהוא נותן ביותר בשנים אלו הוא למזון שבע שני הרעב, ולזה אמר לפרעה **יעשה פרעה ויפקד** וגו' פירוש שישתדל הוא במעשה זה וגם יעשה לאחרים כדי שלא יתעצל אדם בדבר זה בהכנת שבע שני השבע לזרוע בכל היכולת, **וחמש** פירוש יזרזם לבלתי התרשל מטעם ראות הדבר מרובה ביותר. או יאמר **וחמש** שיקח הוא מכולן חמישית לפרעה, הגם שהמשפט הוא מעשר (ש''א ח' י''ז) יקח בשנים אלו חמישית בשכר הודעת הדבר ממנו, וגם שיעשה עמהם חסד שכל התבואה שתהיה לפרעה לא נשלח בה יד אלא תהיה עומדת לפרנסתם למוכרה להם בשני הרעב כאומרו והיה האוכל לפקדון בזה רמז למה שכתבנו כי לא ישלח יד בה גם שלא ימכור מהתבואה לזולת בשני רעב עד שיקדמו הם לקנות צורכם וכמו שאפרש בפסוק שאחר זה:
@36 **לשבע שני הרעב אשר וגו'**. פירוש קודם כל דבר יהיה סיפוק ארץ מצרים לפרנס רעבונם ואחר כך לשאר ארצות, והוא אומרו אחר סיפור רעב מצרים **ולא תכרת הארץ** וגו' כאן כלל כל הארץ:
@38 **הנמצא כזה וגו'**. טעם שלא אמר **הנמצא איש אשר** וגו' **כזה**, כי אז היה נשמע כי נמצא איש אשר בו רוח אלהים אלא שאינו בדומה ולא כן נתכוון לומר אלא שלא נמצא מין זה שיש בו רוח וגו' לא ממנו ולא מקצתו:
@39 **אין נבון וגו'**. פי' אין נבון וחכם שיהיה ראוי לעשות דבר זה כמותך שאתה יש בך רוח אלהים כמו שאמר למעלה שהוא יותר מנבון וחכם:
@43 **אברך ונתון וגו'**. פי' ב' דברים אלו היו קוראין לפניו להודיע ולהשמיע כי הוא השליט בארץ מצרים כמלך:
@44 **אני פרעה ובלעדיך וגו'**. פירוש המלכות היא שלי כי פרעה שם מלכות יגיד **ובלעדיך לא ירים** וגו', פי' אחריו תהיה מעלתו שבלעדיו לא וגו' ולזה אמר בתוספת וא''ו להיות שקדם הזכרת מעלתו באומרו אני פרעה כמו שפירשתי:
@46 **ויעבור בכל ארץ מצרים**. פי' לדעת שדותיה לדעת את אשר יכין עשות וגם אוצרותיה להכין מקומות הצריכין לאצור וההכנות כפי תבונותיו:
@48 **ויקבוץ את כל וגו'**. לפי מה שפירשנו בפירוש (פסוק ל''ד) וחמש את וגו' שיטול החומש יהיה פירוש אומרו **ויקבוץ את כל אוכל** פי' הנוגע לחלק המלך כרשום בדברי יוסף, ולכשנפרש אומרו וחמש ויזרז אפשר לפרש אומרו **ויקבוץ את כל** כפשטו שהיה קונה כל התבואה שעשתה השנה ביותר על השנים, כי לצד שהוא דבר יתר לזורעי אדמה ימכרו הנותר:
@49 **עד כי חדל וגו'**. פי' חדלו לספור אוצרי התבואה אשר ליוסף לצד כי אין מספר מהמביאין שלא היו סופרים לצד טורח שבת מדהבה ולא מדדו את אשר יביאו, והגם שהיו מביאין חומש למה שפירשנו באומרו וחמש, אף על פי כן היו מחלקים התבואה לה' חלקים ונותנים חלק אחד ולא היו יודעים כמה עולה לחשבון המובא, וזה הוא שיעור הכתוב עד כי חדל סופרו של יוסף לספור כי אין מספר לתבואה מהמביאין ויצטרך לספור הפרט ולצרף החשבון לזה חדל לספור:
@50 **וליוסף יולד וגו'**. קשר הכתוב עם שלמעלה ממנו. לומר השגת הטוב של יוסף בז' שני שבע כי מלבד כי צבר בר הרבה והצליח גם כי נזכר לטובה בבנים, וקריאת שם בניו כן יגיד כי הוא שבע רצון כי נשהו ה' כל עמלו והפרהו ה', ופריה זו כוללת בנים ועושר וכבוד:
@50 **בטרם תבא שנת וגו'**. במסכת תענית (יא.) דרשו ז''ל מכאן שאסור לשמש מטתו בשני רעב. ובהכרח לומר שדרשתם היא באם אינו ענין ליוסף שהרי הוא עדיין לא קיים פריה ורביה ואמרו שם בש''ס בפירוש שחשוכי בנים משמשין מטותיהן בשני רעב ולא מצינו שהיו ליוסף בנים קודם אפרים ומנשה וכפי הדין אפילו בשבע שני רעב היה לו לשמש, אלא שהכתוב נדרש באם אינו ענין. ומעתה לא קשה מה שהקשו התוס' שם מיוכבד שנולדה בין החומות ששמש לוי בשני רעב כי כשירדו אבותינו מצרימה היתה שנה שניה לשני רעב, ונדחקו לומר שמדת חסידות שנו ולוי לא היה חסיד בדבר זה, ואין נראין דבריהם לא במה שאמרו מדת חסידות כי מכתוב דרשו לה, ולא במה שיצא מדבריהם כי לוי לא היה חסיד העידה עליו התורה (ברכה לג ח) לאיש חסידך כי הוא היה חסיד שבשבטים, והגם שעל זרעו הוא אומר הענפים יגידו על השורש, וקושית התוס' אינו קושיא, כי דרשת חכמים היא באם אינו ענין ולוי לצד שהיה חסר נקבה לא נמנע מלשמש מטתו כהלכה (יבמות סא: אהע''א סי' א'):
@50 **ועוד** לא אמרו איסור דבר זה אלא לצד צער ישראל ולא לצד צער האומות כי ירעבו כי לא מעלין ולא מורידין, ואז לוי אין חיוב למנוע עצמו לצד צרת האומות כי יעקב היתה לו תבואה כאומרם ז''ל (תענית י:) ולא היה שולח בניו לשבור בר אלא לצד מראית העין דכתיב (מ''ב א') למה תתראו. והגם שאמרו (ב''ר פ' צ''א) ששלמו שערי מכדא זה היה אחר שנה ראשונה. אבל שנה ראשונה ודאי שהיה להם תבואה, ולזה היה מותר לו לשמש, ובשביל יוסף אין להם למנוע עצמן בשביל חשש רעב יחיד, ויוסף אם לא היה טעם שהיה חשוך בנים אפשר שהיה נמנע לצד חשש אביו ואחיו כי ירעבו והם רבים:
@54 **ותחלינה וגו'**. כאשר אמר יוסף הוצרך לומר כאשר אמר יוסף, שבזה נתאמתו דבריו בפתרון החלום יותר, כי מקודם יאמר האומר כי מקרה היה שבאו שני השבע, אבל כאשר שלמו שבע שני שבע והתחילו שני רעב אז צדקו דברי יוסף:
@54 **או** ירצה על זה הדרך **ותחלינה שבע** וגו' ותאמר איך ירגישו בהכר הרעב בתחילת שנת רעבון אחר כל השבע וכל אחד אוצרותיו מלאות בר לא יוכר הרעב תיכף, לזה פירש הכתוב **כאשר אמר יוסף** פירוש שאמר להם (ל''א) ולא יודע השבע בארץ פי' יאכלו ולא ישבעו, ודבר זה הוכר בהתחלת השנה:
@56 **ויפתח יוסף את כל**. טעם שפתח כל האוצרות ולא הספיק בצריך. נתכוון לבדוק בכולן לדעת את אשר יקדים למכור ואת אשר יוכל להתעכב יותר ולא יפסד:
@56 **עוד** להיות שאוכל שדה העיר [אשר] (נתן) סביבותיה [נתן בתוכה] לזה נתחכם ופתח כל האוצרות שבכל מקום ומקום כדי שכל עיר ועיר תהיה סמוכה על מה שלפניה ואינו דומה מי שיש לו פת בסלו. גם לא יצטרכו לטרוח להביא כולן ממקום אחד. גם אולי שנתכוון לפתוח כולן כדי כשיראו אנשי העיר כל הריבוי לא ירעבו כי הרעבון יכנס בלב אדם כשיראה שיש מחסור, וכשיראו כל אוצרות הנפתחות יתקרר חום הרעב שבלבם בוער, ואף על פי כן מודיע הכתוב ויחזק הרעב ולא הועיל בהם לצד חוזק הרעב:
@59 **ונחיה ולא נמות**. טעם הכפל, נתכוון לומר כי אם לא יעשו כן יתחייבו בנפשם בדין העליון ונמצאים מתים בעולם הזה ונידונים לעולם הבא, ובהשתדלותם בדבר יחיו בעולם הזה ולא ימותו לעולם הבא:
@59 **או** ירצה על זה הדרך **ונחיה** או לפחות **ולא נמות**, והכונה היא שאם ישיגו לשבור ברבוי ושופע יחיו כדרך החיים ואם לא ישיגו המספיק ישיגו לפחות הצלת נפשם ממות ברעב:
@60 **אחי יוסף**. פי' נתנו דעתם על האחוה לפדותו:
@60 **עשרה**. אולי הלכו כולן לחשש הרגיל בשני רעב כי תרע עין אדם ברעהו ועל פת לחם יפשעו לגזול ולהרוג איש אחיהו, לזה הלכו כולם כדי שאיש את אחיהו יעזורו, וגם בנימין היו רוצים להוליכו עמם אלא שיעקב לא רצה, והוא אומרו **ואת בנימין לא שלח** וגו', הא למדת שזולת טעם זה גם אותו היה שולח עמהם:
@60 **עוד** נראה שלא היה מוכר יוסף אלא דבר קצוב לכל אחד, ונתחכם בזה לב' דברים, א' נגלה וא' נסתר, הנגלה כדי שלא יתתגר אדם בתבואה, ויש בזה שבח לו ושבח לקונים, שבח לו כדי שישתכר הוא בכל עליית השערים, ושבח לקונים כי הוא לא יעלה השער ביותר, ואחד נסתר כדי שיבואו כל האחים אצלו כמו שכן היה כי באו כולן לקנות כל אחד הקצוב:
@62 **ויבואו בני ישראל וגו' כי היה הרעב וגו'**. הוצרך לחזור לומר **כי היה הרעב** וגו'. נתכוון לתת טעם להבאים שלא תאמר היכן הוזכרו הבאים לומר בתוכם, לזה אמר כי היה וגו' וישנם לבאים. עוד נתכוון לומר שנתחכמו להחביא עצמם ובאו בתוך אותם שבאים לשבור מטעם שהיה הרעב בארץ כנען שבזה לא יכנסו בחשד מרגלות שחשדם יוסף, וזה שיעור הכתוב **ויבואו בני ישראל** ודרך ביאתם היתה בתוך הבאים שביאתם היא **כי היה הרעב** וגו':
@63 **הוא השליט הוא וגו'**. פי' הגם שהוא השליט ואין דרך שלטון להתטפל במכירת התבואה ומה גם בכל כך טורח המופלא אף על פי כן הוא המשביר לכל עם הארץ וטעמו כמום עמו להכיר ברדת אחיו:
@64 **וירא יוסף את אחיו**. פי' ראה אותם בראיית אחים והכיר אחוה להם אלא שאליהם היה מתנכר, והוא אומרו **ויתנכר אליהם** פי' למה שהם אינם מכירים אותו לא יקפידו על דברו אליהם קשות כי הוא להם איש נכרי, ועשה כן להביא בנימין כמו שגילה לבסוף, גם לבחון בהם באמצעות המתגלגל לידע מחשבותם אליו באותו מצב, ונתגלה לו כי מתחרטים הם על אשר כבר עשוהו ולחטא יחשבוהו:
@65 **ויכר יוסף וגו'**. פי' הגם שהוא הכירם לצד שהניחם בחתימת זקן ומטבע אנושי כשתולד הידיעה בלב א' מהשנים גם בלב השני יתעורר בחינת הזכרון כי הלבבות יגידו סודות נעלמים כאומרם (משלי כז) כמים הפנים לפנים כן לב האדם לאדם, וידקדקו בעינים במצח בדיבור והידיעה הולכת וגדלת עד שישלים הבחון, אף על פי כן מודיע הכתוב שהם לא הכירוהו, והטעם לצד ראותו ברום המעלות החליטו הבחינה והרחיקו מלבם מחשוב דבר זה:
@66 **ויזכור יוסף וגו' ויאמר אליהם מרגלים וגו'**. פי' לצד שזכר החלומות אשר חלם להם כפי האמת והם חשדוהו כי שקר בפיו ואומר מה שהוא מקוה להתגדל עליהם, גם הוא נתכוון לכפר עונם ויאמר להם **מרגלים אתם לראות** וגו' ואין בפיכם נכונה:
@67 **ויאמרו לא אדני וגו'**. פי' דבר זה אין מקום לחושדנו בו הגם שהיינו באים בלא סיבה, ועוד **עבדיך באו** וגו' פירוש סיבת ביאתנו הלא היא ידועה וגלויה:
@68 **כולנו בני איש וגו'**. פירוש ובזה אין מקום לחשד ריגול כי המרגלים יבחרו להיות מענפים רבים, וכמו כן תמצא במרגלים ששלח משה, וגם ב' ששלח יהושע לא היו בני איש אחד כי כן דרך הבוחן בענין זה, ואומרו **כנים אנחנו** פירוש אחר שמודיעים עצמם יוצדק כי הם כנים כי הוא הפך משפט המרגלים שלא יודיעו עצמם מעצמ ס:
@68 **לא היו עבדיך וגו'**. אמרו לשון עבר פירוש בביאתם לארץ. כי עתה אחר שהרגיש בהם אינם צריכין לומר שאינם מרגלים כי ודאי שלא ירגלו עוד. או יכוונו לומר שאחר שאמרו טענותיהם לשלול הריגול בהם אין מציאות לסתור טענותם ולחושדם ברוגלים אלא אם כבר היו מרגלים קודם, ולזה אמרו **לא היו עבדיך מרגלים** קודם ולזה לא יכנסו עתה בחשד:
@69 **ויאמר אליהם לא כי וגו'**. פי' לא יאמנו דבריכם כי מעשיכם מוכיחים שבאתם לראות ערות הארץ, והטעם שנכנסו כל אחד בשער אחד כאומרם ז''ל (ב''ר פ' צ''א) שכל אחד מהשבטים נכנס בשער אחד וזה יגיד כי ערות הארץ באתם וגו':
@70 **ויאמרו שנים וגו'**. פירוש טעם שנכנסנו בסדר זה כי אנחנו שנים עשר והאחד איננו לזה נתפרדנו וכל אחד נכנס בשער אחד אולי ימצא אחד ממנו את האחד שאיננו, ואומרו **הנה הקטן את אבינו** זה מופת חותך כי צדק יהגה חיכם כי אמרו דבר שיכול ליבחן:
@71 **הוא אשר דברתי**. פי' שאין אני חוזר מדיבורי הראשון ועדיין הדיבור הראשון במקומו עומד, ואומרו **לאמר** פי' עודני אומר כן:
@71 **או** יאמר על זה הדרך טעם עצמו שאתם אומרים כי באתם לחפש אחר אח האבוד הוא הדבר שנתכונתי בדברי שאמרתי לכם מרגלים כוונתי היא כדרך שאמרתם בפיכם שבאתם לבקש דבר בעיר, והוא על דרך אומרם ז''ל (שם) שאמר להם ואם לא יתנוהו לכם מה תעשו וגו' יעויין שם דבריהם, וגדר זה הוא נכלל בגדר הריגול כל שהם יועצים נגד יושבי העיר, ולדרך זה ידויק על נכון אומרו תיבת **לאמר** והבן:
@72 **בזאת תבחנו**. פי' מתרצה בהבחנה זו הגם שאינה מספקת למה שהוכיח מדבריהם שאמרו שבאו להוציא יוסף כמו שכתבתי:
@72 **או** ירצה שיוצדקו שבדרך רצון באו להוציא יוסף מיד הקונה אם יבא אחיהם הקטון ולבבו יבין את אשר יכוין:
@73 **שלחו מכם אחד וגו'** והם לא עשו כן כי חששו לצרת אביהם על כלן:
@73 **ועוד** שידעו נאמנה שלא ישלח בנימין, וצא ולמד כמה השתדלות עשו כולם יחד עד ששלחו בטענת כי יהודה ערב והוא יביאנו ואם יהודה וכל אחיו בבית כלא מה יהיה בטחונו של יעקב שישלח בנימין וערבו ערב צריך להוציאו מבית משמר:
@73 **או** לעולם לא היה בדעתם להפרד בשום אופן כי היו יראים על הפירוד לבל יהיה אשם להיותו לבדו, ולא נתרצו לבסוף להניח אחד מהם אלא לצד שתלה להם הנסיון בזה כאשר אבאר בפסוק אם כנים וגו' ולא תמותו אז הוכרחו במעשיהם:
@76 **אם כנים אתם וגו'**. יתבאר על דרך אומרם ז''ל בירושלמי פרק ח' דתרומות וז''ל תניא סיעת בני אדם המהלכים בדרך ופגעו בהם גוים ואמרו להם תנו לנו אחד מכם ונהרוג אותו ואם לאו נהרוג כולכם אפילו כולם נהרגין לא ימסרו נפש אחת מישראל יחדו להם וכו' ימסרו וכו' ע''כ. והוא אומרו **אם כנים אתם** פירוש אתם יודעים בעצמיכם אם האמת אתכם **אחיכם אחד** פירוש אחד מכם ולא יחדהו להם יאסר כי אין יראת מות לומר יהרגו כולם ולא ימסרוהו, ולדייק הדבר נתכוון לומר שאם אינם כנים אין להם רשות במשפט להניח אחד מהם כי כשלא יובחנו דבריהם משפט מרגל יש לו ובן מות הוא והרי הם כאלו מיחדים אותו מעכשיו למות ואין הדין כן אלא יהרגו כולם ולא ימסרו נפש אחד מהם. ולא תקשה הלא מצינו כי הוא לקח שמעון ואם כן הוי כיחדוהו, זה אינו כי אולי שהם ייחדו זה מהם:
@76 **או** אפשר שאחר שהסכימו יחד לקחת אחד מהם קדם הוא ובחר שמעון לטעם כי הוא זוגו של לוי ופרד חבילתם:
@77 **ויאמנו דבריכם ולא תמותו**. פי' שאם לא יעשו זה יגיד כי אתם מרגלים ולזה אינם יכולין להניח אחד מהם כי ודאי שימות ואין רשות להם לעשות כן אלא יהרגו כולם וכו', ומעתה יתחייבו מיתה על היותם מרגלים או ירצה לומר שלא ימותו ברעב כי ייטיב עמהם להמציא להם פרנסה והוא מה שאמרו לאביהם (פסוק ל''ד) ואת הארץ תסחרו:
@78 **ויאמרו וגו' אבל**. תיבת **אבל** אין לה משמעות כאן. והמתרגם אמר בקושטא. וגם עליה דן אנכי למה הוצרכו לומר בקושטא:
@78 **עוד** למה האריכו לשון לומר **אשר ראינו** וגו' ולא אמרו סתם, ועוד היה להם לומר אשר מכרנוהו שהוא תכלית העון, ואולי שנתכוונו לומר להיות שצדדו בטעם צרה זו אם הוא בשביל מכר יוסף ודחו טעם זה כפי מה שכתבתי למעלה (ל''ז כ') שכפי הדין דנוהו להריגה ואם כן המכר שעשו לו הוא אדרבה מדת החסד, ואם על שגרמו צרת אביהם אדרבה דבר זה יוסיף לו מכאוב ולא יעשה ה' יסורי עון צער אביהם בדבר שיגדל עוד צער על צערו, ואשר על כן לא מצאו עון ואמרו **אבל אשמים** וגו' **אשר ראינו** וגו' פי' שעל כל פנים היה להם לרחם עליו בראות אחיהם מתחנן על סכנת נפשו ונתאכזרו עליו ודבר זה מגונה לצדיקים לעשותו על כן באה וגו':
@78 **או** ירצה על זה הדרך להיות שראו כולם יחד באו למשמר חשבו בדעתם בשל מי הרעה, ולהיות שמכר יוסף היה לאות בין עיניהם כשבאו לתלות בו מצאו סתירה לדבר מצד ראובן שנתפס עמהם והוא לא היה בתוך המוכרים, לזה הכריחו ואמרו **אבל אשמים** וגו' פי' הן אמת אם נאמר שהצרה באה בעד המכר יקשה לנו ראובן לא מכר אבל אשמים וגו' **אשר ראינו צרת נפשו** וגו' כשרצו לשלוח יד בו ובדבר זה היה ראובן שוה עמהם ההוא אמר (ל''ז כ''ב) השליכו אותו אל הבור ופשיטא כי יתחנן יוסף אליהם ביותר בהשליכו אל הבור לפחד הנפילה והבל הבור והנחשים ועקרבים גם למות שמה ברעב ובצמא ואין לך מיתה משונה כזו ויחנן קולו להם ולא שמעו לקול תחנתו ובזה יד ראובן עמהם, והוא אומרו **על כן באה אלינו** פירוש יחד הצרה, וכל זה כשנאמר כי דבריהם אלו היו כשהכניסום במשמר. וטעם שסדר הכתוב דבריהם באחרונה הוא לצד שלא רצה להפסיק תוך כל דברי יוסף, אבל אם נאמר שדבריהם אלו היו אחר שהסכימו לאסור אחד מהם והם יעלו לשלום כסדר הכתוב צריך לתת טעם למה לא נתעוררו לחוש לאשמת אחיהם עד עתה. ואולי כי קודם לא הרגישו וחשבו כי אדם בעל בחירה ורצון להרע ולא עון יוסף גורם כי לדעתם מחויב היה להם כמו שפירשנו במקומו (שם כ') מה שאין כן כשאמר להם אחיכם אחד יאסר וגו' ויעשו כן פירוש יחדו הם אחד מהם בזה נתעוררו מהנדמה כי הוא עון יוסף כמו שהם נתאכזרו על אחיהם לזה בא להם הצער בדרך זה שאסרו אחד מהם ביד איש נכרי. וכבר רשמתי בכמה מקומות כי העון יוליד בדמותו בצלמו בסוד אומרו (תהלים ס''ב) תשלם לאיש כמעשהו וכמו כן הדברים כאן שהכאיב להם לבם בצרת אחיהם, והוא אומרו **אבל** פי' אם היה המקרה זה בדרך אחר לא היינו מצדיקים שעל סיבת יוסף באה אלינו אבל עתה ודאי אשמים אנחנו אשר ראינו צרת נפשו בהתחננו:
@78 **ועוד** היה להם לאות כיון שנתייחד שמעון דכתיב (כ''ד) ויקח מאתם את שמעון מזה ידעו כי דבר יוסף הוא הסובב כי זה הוא היועץ עצה רעה על יוסף דכתיב (ל''ז י''ט) ויאמרו איש אל אחיו ואמרו ז''ל (תנחומא ויחי) שהם שמעון ולוי:
@79 **ויען ראובן אותם וגו'**. צריך לדעת איך יוצדק לומר מענה על זה, גם אומרו **לאמר** ב' פעמים גם אומרו **וגם דמו** וגו':
@79 **אכן** הכוונה היא שבא להשיב למה שאמרו שהצרה באה על אשר לא רחמו על אחיהם בהתחננו וגו' ולטעם זה יכנס גם ראובן, לזה ענה ואמר, והוא אומרו **ויען ראובן אותם לאמר** כי הוא לא יחשבו לו עון על זה כי הלא אמרתי אליכם אל תחטאו בילד וגו', והגם שלא אמר להם כן בפירוש אלא ויד אל תשלחו בו השליכו אותו (ל''ז כ''ב) וגו', עם כל זה כוונתי היתה לאמר לכם אל תחטאו בילד, והוא אומרו לאמר אל תחטאו, וכמו שהעיד הכתוב באומרו להשיבו אל אביו:
@79 **ואם** תאמר ועל מי סמך ראובן שיכירו אחיו כוונתו שכן היתה ואדרבה לדעתם עשו יותר רחמנות במכירתו מהניחו בבור כמו שכן אמר הכתוב (שם כ''ז) שאמר להם יהודה לכו ונמכרנו וגו' וידינו אל תהי בו ומה תרעומת מתרעם ראובן באומרו הלא אמרתי וגו' כיון שכדבריו עשו והוסיפו לרחם כנזכר. דע כי עיקר טענת ראובן היתה באומרו ויד אל תשלחו בו כמו שפירשתי שם שנתכוון להצילו מידי אדם שהוא בעל בחירה ורצון זה הוא עיקר הכוונה, וטענה זו צודקת גם כן לבל ימכרוהו לנכרים שמעשיהם מעשה בחירי, והמכר גם כן מכניסו בגדר סכנת מות מהנכרים, וגם שישנו בספק דבר רע. וצא ולמד מה שאמרו ז''ל (ב''ר פ' פ''ו) שקנה אותו פוטיפר למשכב זכור ועל זה נסתרס, והוא אומרו **אל תחטאו** אתם **בילד** לעשות בו דבר אלא השליכוהו אל הבור וממה נפשך אם הוא חייב מיתה חיות הנמצאות שם יהרגוהו ואם לאו יהיה לאות החיים מה שאין דבר זה בשליחות ידי אדם, **ולא שמעתם** פירוש לא הבינותם דברי, ומה שאמרו שהצרה באה על האכזריות ושלא קבלו התחננותו ולעולם בגוף המעשה לא עשו עולה לא כן הוא אלא גם **דמו הנה נדרש** כי חייבים הם בשליחות ידם בו ונתונים היו בסכנת מרגלים שהוא משפט מות, ולצד זה גם כן לא יכנס ראובן באשם עמהם כי הוא לא היה במכר, ומעתה ראובן נלכד להיות עמהם לבד, ובגמר הדרישה יתחייב המחוייב ויפטר הזכאי בדינו. וגם למה שפירשתי באומרו אבל אשמים שהתעוררותם היתה לצד תפיסת שמעון לבד יהיה פירוש הכתוב גם כן כדרך זה:
@80 **והם לא ידעו וגו' כי המליץ בינותם**. פי' לצד שראו המליץ בינותם בשאר דברים חשבו כי אינו שומע לשונם:
@80 **או** יאמר כי המליץ בינותם ואז לא היה להגיד לו:
@81 **ויקח מאתם את שמעון**. פי' הם יחדו אותו ולקחו. או הוא ברר לעצמו, וכמו שכתבתי בפסוק (י''ט) אם כנים:
@82 **ולהשיב כספיהם**. טעם שלא דבר הכתוב בשיעור שהתחיל לדבר וימלאו וגו' היה לו גם כן לומר וישובו, או היה לו לומר למלאות את וגו' ולהשיב, ואולי כי הממלא לא ידע השבת הכסף והנאמן ביתו הוא השיב, או צוה שיהיה המילוי בפרהסיא והשבת הכסף בהצנע. עוד נתכוון להקדים לומר למלאות כליהם בר ואחר שמלאו וגו' הוסיף לומר להשיב וגו' ולתת להם צדה וגו', והכוונה בזה כי לא רצה לומר הכל יחד כדי שלא תהיה עין הממלא צרה במילוי:
@83 **וישאו את וגו' וילכו**. פי' שלא נתעכבו אלא שיעור שנשאו שברם ותכף הלכו, שאם לא כן לא היה צריך להודיענו שנשאו שברם וגו':
@94 **לאמר את שני בני וגו'**. טעם אומרו **לאמר** במקום זה. נתכוין לומר כי לא הוציא מפיו דבר זה בפירוש משום קללת חכם (מכות יא.), אלא אמר דבור שהמובן ממנו הוא זה ולא הוציא מפיו בפירוש מיתת בניו. ואומרו **את שני** פי' שנים מהנמצאים כי ד' היו לו, ואומרו **תמית** תעניש, ומצינו עונש כזה כאומרם ז''ל (ויק''ר פ''ז) בפ' ובאהרן התאנף וגו'. וטעם שלא רצה ראובן לחייב עצמו אלא בב', לצד כי הוא עונש עליון שיהיה חסר מצות פריה ורביה, לזה לא שעבד אלא דבר שאינו מזיקו לעולם הבא, ולזה נתחכם יהודה כשראה שלא נתרצה אביו לדברי ראובן ואמר (מ''ג ט') וחטאתי לאבי כל הימים סכן עצמו גם בעולם עליון:
@94 **תנה אותו על ידי**. אולי כי בטוח היה להיותו נקי ובר מעון יוסף כי לא יארע לו דבר בלתי הגון, לזה דקדק לומר **תנה אותו על ידי** ואני אשיבנו מה שאין כן שאר אחים כי הם אשמים במכירת יוסף:
@95 **כי אחיו וגו' והוא לבדו**. פי' בא לתת טעם איך הוא חש על ספיקו של בנימין מודאו של שמעון האסור במשמר מצרים בערבון וכשלא יביאו בנימין הנה הוא מחויב מות, לזה אמר כי לזה יש להקפיד כי אחיו מת מה שלא אירע כן לאחד משאר אחים, ועוד אין חסרונו כחסרון שמעון כי הוא לבדו נשאר יחיד לאמו מה שאין כן שמעון כי ה' אחים יש לו. ועוד ספק זה ספק מוכרע הוא, והוא אומרו **וקראהו אסון** ולא אמר אם יקראהו אסון וגו', ודקדק לומר **בדרך אשר תלכו בה**, רמז כי יוסף אחיו הלך בדרך שהם רגילים ללכת בה בתמידות מחברון לשכם ואף על פי כן טרוף טורף וכמו כן זה יש לחוש לו לאסון אפילו בדרך אשר אתם הולכים בו בתמידות בלא שום חשש:
@97 **כאשר כלו**. אולי שהכונה היא שלא נשאר אלא שיעור המספיק לזמן הליכתם וביאתם, ויאמר גם על זה כלו כי צריכין להביא עוד. או לפי מה שאמרו ז''ל (תענית י:) כי יעקב הכין תבואה לשני רעב היו אוכלים במשך הליכתם וחזרתם מהמזומן אצלו, ולזה דקדק הכתוב לומר כלו השבר אשר הביאו ממצרים לומר אותו השבר כלו ולא כל השבר שהיה להם:
@98 **ויאמר אליו יהודה לאמר**. אומרו תיבת **לאמר**. פי' שאמר אליו יהודה הצעת דברים לאמר אליו התשובה, וההצעה היא העד העיד וגו', והאמירה היא אם ישך וגו', ונתכוין הכתוב בזה לשלול תשובה מאופן אחר הנשמעת מההצעה הנזכר והוא כי לצד שהעיד וגו' בהכרח שיקחו בנימין וילכו בין לרצון בין שלא לרצון, לזה אמר לאמר פי' הודעה זו גזירתה היא מה שיאמר אחר כך:
@98 **או** ירצה על זה הדרך **לאמר העד** וגו' פי' אמר לנו זה והעיד עלינו עדים בהתראתו. עוד ירצה לומר השיבני על טענה זו אם יש לך תשובה להשיב לאדוני הארץ. עוד ירצה שיש עוד לומר טעם אחר מלבד זה והוא סכנת שמעון הנתון בבית כלא לערב הוכחת דבר כי לא מרגלים:
@98 **לא תראו פני וגו'**. נתכוון בזה לשלול טענה כי יאמר יעקב שיעשה הוכחות וראיות המספיקים לפני מלכים ויועצי ארץ להכיר כי אינם בגדר ספק מרגלים ובזה תמה טענת האיש החושד בהם, לזה אמר העד בנו לאמר לא תראו פירוש שאינו מתרצה לראות פנינו זולת בביאת בנימין, ומעתה אינם יכולים לעמוד לפניו בשום אופן ואיך ילכו לקנות התבואה ממנו. ואולי כי לזה כפל יהודה דבר זה ב' פעמים כי תנאי זה של בנימין מעכב הגם שיוסר חשד המרגלות:
@103 **ונחיה ולא נמות**. פי' נחיה חיים בלא צער, ואומרו **ולא נמות** פירוש ולפחות לא נמות הגם שיחיו חיי צער. או ירצה באומרו **ולא נמות** לדייק בא אבל אם לא ילכו לא תאמר שיחסר להם חיות המספיק לבד אלא אפי' חיי צער לא יחיו אלא הם מעותדים למות:
@103 **או** ירצה שאם לא ילכו עתידים למות בעולם העליון כי יאמר ה' להם למה לא טרחו לחיי נפשם:
@103 **גם אנחנו**. אומרו **גם** פי' מלבד בנימין שאתה ירא עליו בהליכה זו יחיה וגם המה, וזולת זה הנה הוא והם מתים ודאי ואינו מן הראוי שימותו כולם וגם בנימין משום ספק בנימין, לו יהיה שספק סכנת בנימין מוכרע כאמור בטענת יעקב כמו שפירשתי בפסוק (מ''ב ל''ח) כי אחיו מת. ואומרו **גם אתה** אחרו הזכרת חיות אביהם לחיותם, אפשר שנתכוונו לדבר כפי הדין (יו''ד רנ''א) שחיי אדם קודמין אפילו לחיי אביו. או אפשר שנתכוונו לדבר בדרך לא זו אף זו והוא העליון. או יאמר עז''ה לא הם לבד בהליכתם יחיו אלא גם אתה צריך לדבר כי אין לחם בכל הארץ זולת במצרים והוא מסוכן אם לא ילכו, ואומרו **גם טפינו** באחרונה כי בניו של אדם חביבין עליו מגופו. וצא ולמד מדוד שאמר על אבשלום הגם שהיה רודף אביו (ש''ב י''ט) מי יתן מותי וגו':
@104 **אנכי אערבנו וגו' וחטאתי וגו' כל הימים**. טעם אומרו כל הימים. רז''ל (ב''ר פ' צ''א) אמרו עולם הבא שכולו ימים. ובפ' הגולין (מכות יא:) אמר רב יהודה נידוי על תנאי צריך התרה מנלן מיהודה דכתיב אם לא הביאותיו וגו' ואמר רבי שמואל בר נחמני אמר ר' יונתן מאי דכתיב יחי ראובן וגו' כל אותם מ' שנה שהיו ישראל במדבר היו עצמותיו של יהודה מתגלגלין עד שעמד משה וכו' ע''כ. ואם תאמר דלמא עונשו של יהודה היה שלא כפל התנאי כתנאי בני גד וכו' (קידושין סא:) שהמעשה קיים על כל פנים, לזה ראיתי להגאון רא''ם שתירץ כי בדבר זה לא היה טועה יהודה וגם אביו, אבל נידוי שעל תנאי שצריך התרה אפשר שיטעה יהודה וגם אביו לפי שלא נודע דין זה אלא ממקרה שקרה ליהודה וכו' מה שאין כן כפל התנאי שמבואר בתורה. דבריו נפלאו ממני ממה נפשך אם לא היתה התורה ככתבה ידועה לאבות אם כן מנין היו יודעים כי בני גד ובני ראובן שאלו עבר הירדן והתנה משה עמהם תנאי כפול, ואם היו יודעים כל ההלכות הנשמעים מתורת משה למה תגרע הלכה זו שלא ידעו אותה. ותמצא שאמרו במסכת חולין שכל ההלכות נאמרו בסיני אלא שנשנית כל אחת במקומה כמו גיד הנשה שהגם שנאמרה בפרשת וישלח בענין יעקב בסיני נצטוו עליו אלא שנכתבה במקומו וכמו כן כל ההלכות, ואם כן דין זה הנלמד מיהודה כמו כן נאמר בסיני ומעתה אין הפרש בין ההלכות להיותם נלמדים בסדר זה או בסדר זה, ולכשנאמר שיעקב ידע הכל כמו שידע זה ידע זה:
@104 **ועוד** גדולה מזו אני רואה כי דין זה דתנאי כפול במחלוקת שנו ליה כי ר' חנינא בן גמליאל סובר שאין צריך לכפול התנאי וטעם בני גד ובני ראובן לטעמים האמורים שם בגמרא מה שאין כן דין נידוי על תנאי תלכה מוסכמת היא ואין חולק עליה ואם כן אדרבה יותר יש לתלות עונשו של יהודה לצד שלא כפל התנאי להיותו סובר כדעת רבי חנינא בן גמליאל וכמו כן סבר יעקב ולצד שאין הלכה כן היו עצמותיו מתגלגלים בארון ממה שנאמר כי נידוי על תנאי צריך התרה הלכה פשוטה וטעו בה יעקב ובניו:
@104 **והנכון** הוא כי כוונת דברי רב יהודה שאמר נידוי על תנאי צריך התרה הוא על זה הדרך אם נידה על תנאי ולא כפל לומר ואם לא לא אהיה בנידוי זה הוא שצריך התרה אבל אם כפל ושלל אינו צריך התרה. וכיוצא בה גם כן אמר שם בש''ס (מכות יא.) אמר ר' אבהו קללת חכם אפילו על תנאי היא באה מנלן מעלי וכו'. ואם תאמר מה צריך להשמיענו רב יהודה בזה משנה (קידושין פ''ג מ''ד) ערוכה היא כל תנאי שאינו כתנאי וגו' המעשה קיים. זה אינו כי בנדרים ושבועות העיקר הוא הלב כמאמר ר' עקיבא שדרש (שבועות כ''ו) האדם בשבועה שצריך לבו ופיו שוים וזולת זה אינו שבועה והוא הדין נדרים ונדויים, ומעתה יאמר אדם כי בנידוי הגם שלא התנה תנאי כפול כיון שלבו לא גמר לנדות אלא אם יהיה כן למה יתחייב בדבר שלא היה כן בלבו והתורה אמרה האדם בשבועה, לזה הודיע רב יהודה שאם לא כפל הגם שעשאו נדוי על תנאי צריך התרה, ואין הוכחה לדין זה אלא מיהודה, וטעם דין זה כטעם דין זה קללת חכם האמורה בסמוך ואין לנו אלא מה שגילה לנו הכתוב במעשה יהודה ובמעשה עלי, גם מעשה יעקב שקלל (ויצא לא לב) עם אשר וגו' לא יחיה וכולן לא היה סתירת הדבר בכפל התנאי:
@104 **ומה** שכתב הרא''ם כי נאמר הכפל ולא נכתב כבר דחינו הדברים ואין צורך להוסיף לדחותם:
@104 **שוב** ראיתי להתוספות שכתבו בפירוש דברי רב יהודה שטעם נידוי יהודה שחל הגם שהוא על תנאי הוא לצד שלא היה בידו לקיימו ולכך חל גם על התנאי וגו' אבל שאר תנאים שבידו לקיימן כגון שמנדין את האדם שלא יעשה דבר ודאי לא חל הנידוי כלל עד כאן:
@104 **והנה** לדברי התוס' הגם שכפל המנדה התנאי אף על פי כן חל עליו לצד שאין בידו לקיימו, וזה הפך מה שכתבנו. ולא ידעתי מה יפרשו במימרת רבי אבהו הסמוכה לה שאמר קללת חכם אפילו על תנאי ומוכיח מעלי שאמר לשמואל כה יעשה לך וגו' אם תכחד והדבר היה בידו לומר לו תכף ומיד ובידו של שמואל לומר לו. ויש ליישב. ואל תקשה והלא דברי רב יהודה סתם נאמרו נידוי על תנאי ולא חלק בדבר שיכול לעשותו לדבר וכו', כי סמך על ההוכחה דון ממנה כמוה וכמציאותה. גם למה שפירשתי שכוונת רב יהודה הוא על הכפל לא חש עליך רב יהודה לטעות כי סמך על המלמד דעת ממנו ובו לא היה כפל:
@104 **גם** הצצתי בדברי התוס' וראיתי כי סוברים כנ''ל שמנדה על דבר שהוא בידו לעשותו הגם שלא התנה תנאי כפול אין צריך התרה ואם כן אם לא היה מטעם שחל הנידוי על יהודה שאין בידו לקיימו הגם שלא כפל התנאי אין המעשה קיים ואין צריך תנאי כפול ודלא כדברי הרא''ם. נמצינו אומרים שני טעמים בדין המנדה על תנאי האחד לצד שלא כפל הוא שצריך התרה ומדין תנאי כפול והב' לצד שנידה על דבר שאינו ברשותו והוא דעת התוספת ונשאר לנו לדעת למה לא התיר יהודה נידויו:
@104 **וראיתי** להראב''ד ז''ל בהשגותיו על רמב''ם בפ''ז מהלכות ת''ת השיג על מה שכתב רמב''ם שם תלמיד חכם שנידה לעצמו ואפילו נידה על דעת חברו ואפילו על דבר שחייב עליו נידוי הרי זה מתיר לעצמו ע''כ, השיגו כי למה לא התיר יהודה לעצמו ועל כל זה קשה לי יעקב למה לא התירו ע''כ:
@104 **וראיתי** להרשב''א שכתב כי מה שיכול חכם להתיר נידויו דוקא בדלא מחויב נידוי וכההיא דמר זוטרא וכו'. ולדרכו של רשב''א לא קשה אלא קושית יעקב למה לא התירו אבל יהודה אינו יכול, אבל על כל פנים קשה היה לו ליהודה לקבץ ג' הדיוטות ולהתיר לו, ואין בזה דין על דעת חבירו שצריך מדעתו, שהרי נסתלק חיובו ששעבד עצמו להביאו לפניו, ועוד היה לו להודיעו, ופשיטא כי לא יחפוץ לצער את יהודה בנו ללא דבר. והדברים פשוטים אצלי כי על כל פנים אין קושיא על יעקב כי לכשנאמר שידע הדין שצריך התרה סמך כי יהודה יתיר על ידי אחרים אחיו וכיוצא בהם ואין קושיא על יעקב זולת על יהודה יש לנו לפקח לדעת טעמו:
@104 **והנה** לפי מה שהעליתי בפירוש דברי רב יהודה שטעם ההתרה היא שלא כפל התנאי כפי זה טעמו של יהודה הוא שהיה סובר כר' חנינא בן גמליאל שאינו צריך כפל התנאי ובזה טעה. אלא תקשה ולמה לא הוכיחו לרחב''ג מיהודה שנענש כי דברי רבי יהודה למה שהעמדנו בדין כפל התנאי הם דלא כרחב''ג. ולסברת התוס' שפירשו דברי רב יהודה כי טעם שצריך התרת הנידוי הוא לצד שעשאו על דבר שאינו ברשותו בהכרח לומר שנעלם מעיני יהודה דין זה, ויעקב הגם שנאמר שידעו תלה כי יהודה יתיר מעצמו:
@118 **שלום לכם וגו'**. אמר כן האיש מעצמו מבלי דעת כוונתו של יוסף מה היא, ולדבריהם ז''ל (תנחומא) שאמרו כי הוא מנשה יפה כח הבן מכח האב וידע כי יסכים על דבריו. ואומרו **אל תיראו**, לפי שהוכר בפניהם היראה דהיו יראים דכתיב (פסוק י''ח) וייראו האנשים:
@118 **נתן לכם מטמון**. פי' איזה אדם טמן שם הכסף וה' נתנו לכם ביאוש הבעלים ובני נח אינם מצווין על הכרזת אבידה, ולחזק לבם הוציא אליהם את שמעון להראות כי שלום להם:
@119 **ויבא האיש את האנשים וגו'**. אמר כן פעם ב'. להיות כי בפעם ראשונה נפסקה הכניסה כי נתעכבו ועמדו פתח הבית פירוש קודם שיכנסו לבית, והגם שאמר ויבא האיש וגו' ביתה יוסף הוא על דרך אומרו (ויצא) וילך חרנה שהכוונה היא ללכת לחרן, ולעולם עדיין לא נכנסו, וטעם שרצו לדבר עמו קודם על הכסף לדעת ביאתם למה אם לטוב אם לרע לדעת מה יעשה ישראל ואחר תשובתו אליהם הוצרך פעם ב' לומר ויבא האיש, ביתה יוסף פירוש בית המשובח שלו:
@121 **ויביאו לו וגו' הביתה וגו'**. פי' לחדר המיוחד לו והם היו בחדר אחר בבית עצמו, והודיע הכתוב שנכנסו אצלו למקום שהיה בו להכנים המנחה:
@122 **וישאל להם לשלום**. פי' מתחילה שאל בשלומם כי הוא מהמוסר להקדים לשאול שלום את אשר לפניו, והוא אומרו **להם לשלום** ואחר כך שאל על אשר איננו שם השלום אביכם וגו':
@122 **השלום אביכם הזקן וגו'**. קשה איך יוצדק לשאול השלום קודם שאלת העודנו חי. ואם הכונה בשאלת השלום היא מה שפירש באומרו העודנו חי למה כפל. גם בתשובת האחים קשה שאמרו שלום וגו' עודנו חי אחר שאמרו שלום מה חידוש באומרם עודנו חי. ואולי שנתכוון לומר אם ככוחו אז כחו עתה או הוחלש לצד הזקנה, והוא מה שדקדק לומר **עודנו** פירוש כמות שהיה בזמן הקודם, ולזה נתחכם גם כן לסדר שאלת שלום קודם שאלת העודנו חי להבין כוונתו כמו שפירשנו, וכפי זה שאלת העודנו חי אינה נכללת בשאלת השלום לו כי גם על אדם שהזקין ואפסו קצת כוחותיו כפי הטבע יאמר עליו שלום לו:
@130 **מלא וגו' ואת גביעי וגו'**. צריך לדעת טעם יוסף בעניינים אלו. ואם לצערם הלא מעשיו מוכיחים כי גמר בלבו השלום ואכל ושתה עמהם והראה להם שלום. ואולי כי נתכוין לג' דברים. הא' כדי שיכופר להם עון הגניבה שגנבוהו היה עושה להם דברי חשד כדי שיהיה הבושת על מין העון עצמו של יוסף ויכופר עונם. והב' לראות אם יתנו נפשם על בנימין ובאמצעות זה יכיר כי מודדין מדידת אחוה עם אחיו ויכפר להם עונם, הג' לרמוז להם ענין הגניבה אולי יתחילו להרגיש כי יש מי שמכיר מעשיהם בבית הלז, וכן מצינו לו שהיה רומז להם הדבר בפרטים אחרים דכתיב (מ''ג ל''ג) וישבו לפניו הבכור כבכורתו וגו' וכאלה רבות:
@134 **הלא זה וגו'**. לא הוצרך להזכירו להיות האיש הלז הוא הנותן הגביע באמתחת בנימין, לזה לא היה צריך להזכירו ומובן אצלו הדבר שעל הגביע הוא מדבר, וכוונת דבריו הוא להודעת טעם הרגשתם בגניבה תיכף ומיד כי זה יגיד שהדברים מעשה ידיהם אשר כוננו, לזה אמרו הלא זה אשר ישתה אדוני בו פי' בתמידות ומצד זה הוא דבר הרגיל להשתמש בו ומזה ידעו תכף לגניבתו, ואומרו **והוא נחש ינחש** בא לתת טעם לדבריו בדרך זה בפשיטות שהם גנבוהו ולא חשד בזולת, לזה אמר נחש ינחש פירוש נחש מה שלפניו ינחש מה שעתיד להיות ובו נחש וידע כי הם יגנבוהו, ואולי כי לטעם זה נתנו לב עליו אחר הליכתם:
@134 **הרעותם אשר עשיתם**. קשה אחר שאמר למה שלמתם רעה תחת טובה מה מקום לומר **הרעותם** וגו'. הלא אין לך רעה בעולם כמשלם רעה תחת טובה. ואולי שנתכוין לסתור הוכחת ההפכיות ממה שהחזירו הכסף השכוח באמתחתם, כי זה האיש אשר אליו גלו שהשיבו עמהם כסף הנמצא אתם ואם כן יעשה ק''ו הן כסף וגו' ואיך נגנוב כמו שהשיבוהו אחר כך, לזה אמר **הרעותסאשר עשיתם** כי בזה סתרתם לאותה חזקה שהחזקתי אתכם בכשרות במעשה אשר עשיתם בהשבת הכסף והורעה חזקתם כי לא אנשי אמת הם ותולה אני המעשה בדרך מקרה והוא מהמקרים אשר יעשו גם הגנבים ולא ממוסר השכל:
@134 **עוד** ירצה באומרו **הרעותם אשר עשיתם** פירוש בהשבת הכסף כי באמצעות דבר זה גילו אדעתם כי מה שהחזירו הכסף זה אדרבא מהרשע עשו כן להחזיק אותם באנשים בעלי אמונה שבאמצעות זה יאמינו בהם וימצאו מקום לגנוב דברים יקרים וחשוב מכסף המושב, כי מחזיק הגביע ליקר הערך מהכסף שהשיבו עמהם:
@136 **למה ידבר וגו' כדברים וגו'**. פי' מה מקום יש לו לדברים, לא מבעיא הדברים עצמם אלא אפילו הדומה להם אין ראוי לו לדבר כל דדומה לכיעור זה חלילה לעבדיך לעשות אפילו דומה לזה, והוא אומרו **כדברים האלה**. ואומרו **הן כסף** וגו' והוא כבר סתר ק''ו זה כמו שפירשתי, נתכוונו לסתור טענתו בין מה שפירשנו כי כוונתו לומר כי סתרו לחזקת השבה כי אינה לצד אמונתם אלא דבר מקרה אמרו כי הן אמת כי יהיה דבר זה דרך מקרה באיש גזלן לעשות כדברים האלה, אבל לא בסדר זה שאחר שזכה בו והוליכו למקום רחוק ימים רבים אפילו לאיש נאמן קשה הוא אצלו להשיב גזל הנאכל, ואנו השבנוהו אליך מארץ כנען אחר שזכינו בו למרחוק, מציאות זה לא ימצא אלא בבחינת הנאמן גמור. וכנגד מה שנתחכמת לומר כי למרמה נתכווננו בהשבת הכסף, הן אמת כי דבריו יוצדקו אם היה הגביע נחשב אצלם לפעולתו לנחש יהיו הדברים כטענתו אבל כפי האמת הוא אצלם כשאר כסף בעלמא כי לא ינחשו וגם לא ידעו לנחש בו ואינו אצלם אלא כשאר כסף והוא אומרו **איך נגנוב** וגו' **כסף** וגו' פי' אינו אצלינו הגביע אלא בגדר כסף. ומה שאמרו **או זהב** נתכוונו לומר שאינם יודעים הגביע שהוא טוען עליו אם הוא כסף או זהב וזה יגיד שאין להם ידיעה בו כל עיקר:
@138 **אשר ימצא וגו'**. פירוש כמשפט בן נח שנהרג על הגניבה (סנהדרין נז) וגם אנחנו מחייבין עצמינו להיות עבדים:
@139 **ויאמר גם עתה וגו'**. צריך לדעת אומרו **גם** מה נתחדש עתה לענין הדין. ועוד קשה אומרו **כדבריכם כן הוא** ורואני שהוא הפך דבריהם כי הם אמרו אשר ימצא אתו ומת והוא אמר יהיה עבד. ואולי שנתכוין להשיב על מה שאמרו הן כסף אשר מצאנו וגו' ואמר גם עתה אחר שנחשדו בדבר אני מצדיק דבריכם שלא גנבתם ועומדים אתם בחזקת אמונה ראשונה אבל אינכם יכולין להצדיק כל אחד ואחד מכם כי אפשר שימצא בהם אח לא לאמונה עשה ואותו נטל הגביע ואין טענתי אלא על אחד מכם ומשפטו הוא יהיה לי עבד, והגם שחייב מיתה הדבר תלוי בידי לשעבדו עד עת אשר אחפוץ להמיתו:
@139 **או** ירצה שטען שאין בפיהם נכונה שאמרו ומת כי אין חיוב מיתה אלא אם יש עדות על הגניבה שראוהו שנטלו אבל מציאות זה אינו אלא אומדנא לא יתחייב אלא מדינא דמלכותא, ואומרו **ואתם תהיו נקיים** כי בחזקת כשרות עומדים ולא יתפשו מדין עשרה שנמצאת ביד אחד מהם הגניבה כיון שאין עדות עליהם שנועדו יחד וגנבו:
@144 **הלא ידעתם כי נחש וגו'**. בזה נתכוון לסתור גם כן טענתם שיאמרו מי גילה לכם סוד זה כי אנו הגנבים זולת אם נאמר כי מעשה ידיהם המה והוא עשה הדבר, לזה אמר הלא ידעתם כי נחש וגו' ומזה ידע:
@144 **ואומרו איש אשר כמוני** פי' מן הסתם כל אדם גדול כמוני ינחש לדעת נסתרות אשר יוכל השיג ואם כן יתגלה הדבר אלי והיה לכם לחוש על הדבר שלא יפלא ממני:
@145 **מה נאמר לאדוני**. פי' אמירה בדרך ריצוי. **מה נדבר** פירוש דיבור קושי בדרך מלחמה, **מה נצטדק** פי' במשפט אם נבוא לפני דיינים כי אין מפלט להם בכולן ואין זה אלא מעשה אלהים המה להפרע מהם עונם כשמצא לגבות חובו, ולצד כי העון שבידם הוא לכלם יחד הננו עבדים לאדוני וגו':
@145 **עוד** ירצה באומרו **מה נצטדק** כי מעתה כשנמצאת הגביע באמתחת בנימין אין עוד מקום לק''ו האמור בדבריהם הן כסף וגו', כי בנימין לא היה מהמחזירים כסף השב:
@145 **גם אנחנו**. פי' הגם שלא נמצא בידינו הגניבה, ואומרו **גם אשר** וגו' פירוש לצד שהעון שהוכר אצלם אין בנימין בכלל העון לזה אמרו גם אשר נמצא וגו', על דרך אומרם (סנהדדין צג) שני עצים יבשים וחד רטוב וכו' וכיון שכולם נלכדו בעונם והוא היה עמהם נלכד בשחיתותם:
@145 **או** ירצה שלא יבין שעודם בדעת ראשון שאמרו אשר ימצא אתו ומת וגם אנחנו, לזה גמרו אומר כי אין הסכמת מות ביניהם אלא גם אשר נמצא משפט עבדות יש לו ולא משפט מות, ומטעם שאין עדים על הגניבה ויוכל לומר לא ידעתי מי שם וגו':
@146 **חלילה לי וגו'**. פי' אם ה' מצא לכם עון אני לא אדון על הדבר אלא על מה שנתגלה לי מהמשפט הצדק ועל חטא זה אני שופט האיש אשר נמצא וגו' יהי' לי עבד וגו' ואתם עלו לשלום. ובזה נחה דעתי במה שרואני שדבר יהודה כדברים האלה שזה יגיד כי כלו לו דברי פיום וקבל המשפט ואיך תוך כדי דיבור ויגש אליו ודבר דברים עתיקים, ולדברינו צדקו הדברים כי מקודם חשב כי מה' יצא הדבר כי מצא האלהים עונם וכשראו שלא קבל יוסף אלא בנימין לבד אמר הרי זה לך לאות כי לא על עון נתפסו, ומעתה עמד הדבר לצד בחירת הבחירי, לזה ויגש אליו יהודה:
@146 **חסלת פרשת מקץ**
